APP_TIMEZONE_NAME = os.environ.get("APP_TIMEZONE", "Asia/Jakarta")
try:
    APP_TIMEZONE = ZoneInfo(APP_TIMEZONE_NAME)
except Exception:
    APP_TIMEZONE_NAME = "UTC"
    APP_TIMEZONE = timezone.utc

def app_now():
    """Return an application-local timestamp independent of the host operating system."""
    return datetime.now(APP_TIMEZONE)

def app_now_text():
    return app_now().strftime("%Y-%m-%d %H:%M:%S")

def utc_now():
    return datetime.now(timezone.utc)

# =============================================================================
# SQLITE STORAGE LAYER (users, password reset tokens, analysis history)
# Replaces the previous CSV-based storage. A single SQLite file avoids the
# "read whole file -> overwrite whole file" race condition that CSV storage
# has when multiple users/sessions write concurrently.
# =============================================================================
# Always resolve the SQLite database against the application directory.
# A persistent database service is recommended when hosting on ephemeral cloud instances.
APP_DIR = Path(__file__).resolve().parent
_db_setting = Path(os.environ.get("APP_DB_FILE", "transformer_app.db")).expanduser()
DB_FILE = str((_db_setting if _db_setting.is_absolute() else APP_DIR / _db_setting).resolve())
Path(DB_FILE).parent.mkdir(parents=True, exist_ok=True)
@contextmanager
def get_conn():
    conn = sqlite3.connect(DB_FILE, timeout=30)
    conn.execute("PRAGMA journal_mode=WAL;")
    conn.execute("PRAGMA foreign_keys=ON;")
    try:
        yield conn
        conn.commit()
    finally:
        conn.close()
def db_init():
    with get_conn() as conn:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS users (
                username TEXT PRIMARY KEY,
                name TEXT NOT NULL,
                email TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL,
                created_at TEXT NOT NULL
            )
            """
        )
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS password_reset_tokens (
                token TEXT PRIMARY KEY,
                username TEXT NOT NULL,
                created_at TEXT NOT NULL,
                expires_at TEXT NOT NULL,
                used INTEGER NOT NULL DEFAULT 0,
                FOREIGN KEY (username) REFERENCES users(username)
            )
            """
        )
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL,
                data TEXT NOT NULL,
                created_at TEXT NOT NULL
            )
            """
        )
        conn.execute("CREATE INDEX IF NOT EXISTS idx_history_username ON history(username)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_reset_username ON password_reset_tokens(username)")
def db_username_exists(username):
    with get_conn() as conn:
        row = conn.execute(
            "SELECT 1 FROM users WHERE lower(username) = lower(?)",
            (str(username).strip(),),
        ).fetchone()
    return row is not None
def db_email_exists(email):
    with get_conn() as conn:
        row = conn.execute(
            "SELECT 1 FROM users WHERE lower(email) = lower(?)",
            (str(email).strip(),),
        ).fetchone()
    return row is not None
def db_insert_user(username, name, email, password_hash, created_at):
    with get_conn() as conn:
        conn.execute(
            "INSERT INTO users (username, name, email, password_hash, created_at) VALUES (?, ?, ?, ?, ?)",
            (username, name, email, password_hash, created_at),
        )
def db_get_user_by_identifier(identifier):
    identifier = str(identifier).strip().lower()
    with get_conn() as conn:
        row = conn.execute(
            "SELECT username, name, email, password_hash FROM users "
            "WHERE lower(username) = ? OR lower(email) = ?",
            (identifier, identifier),
        ).fetchone()
    if row is None:
        return None
    return {"username": row[0], "name": row[1], "email": row[2], "password_hash": row[3]}
def db_get_user_by_username(username):
    with get_conn() as conn:
        row = conn.execute(
            "SELECT username, name, email, password_hash FROM users WHERE username = ?",
            (str(username),),
        ).fetchone()
    if row is None:
        return None
    return {"username": row[0], "name": row[1], "email": row[2], "password_hash": row[3]}
def db_update_password(username, new_password_hash):
    with get_conn() as conn:
        conn.execute(
            "UPDATE users SET password_hash = ? WHERE username = ?",
            (new_password_hash, str(username)),
        )
def db_create_reset_token(token, username, created_at, expires_at):
    with get_conn() as conn:
        conn.execute(
            "INSERT INTO password_reset_tokens (token, username, created_at, expires_at, used) "
            "VALUES (?, ?, ?, ?, 0)",
            (token, username, created_at, expires_at),
        )
def db_get_reset_token(token):
    with get_conn() as conn:
        row = conn.execute(
            "SELECT token, username, created_at, expires_at, used FROM password_reset_tokens WHERE token = ?",
            (token,),
        ).fetchone()
    if row is None:
        return None
    return {
        "token": row[0],
        "username": row[1],
        "created_at": row[2],
        "expires_at": row[3],
        "used": bool(row[4]),
    }
def db_mark_token_used(token):
    with get_conn() as conn:
        conn.execute("UPDATE password_reset_tokens SET used = 1 WHERE token = ?", (token,))
def db_invalidate_user_tokens(username):
    with get_conn() as conn:
        conn.execute(
            "UPDATE password_reset_tokens SET used = 1 WHERE username = ? AND used = 0",
            (str(username),),
        )
def db_insert_history_record(username, data_json, created_at):
    with get_conn() as conn:
        conn.execute(
            "INSERT INTO history (username, data, created_at) VALUES (?, ?, ?)",
            (username, data_json, created_at),
        )
def db_insert_history_records(records):
    """records: list of (username, data_json, created_at) tuples."""
    if not records:
        return
    with get_conn() as conn:
        conn.executemany(
            "INSERT INTO history (username, data, created_at) VALUES (?, ?, ?)",
            records,
        )
def db_load_history_for_user(username):
    with get_conn() as conn:
        rows = conn.execute(
            "SELECT data FROM history WHERE username = ? ORDER BY id ASC",
            (str(username),),
        ).fetchall()
    return [row[0] for row in rows]
def db_delete_history_for_user(username):
    with get_conn() as conn:
        conn.execute("DELETE FROM history WHERE username = ?", (str(username),))
db_init()
# =============================================================================
# EMAIL SENDING (Gmail SMTP with an App Password) - for password reset
#
# Configuration (do NOT hardcode credentials in source):
# Set these as environment variables, or in .streamlit/secrets.toml:
#     GMAIL_ADDRESS      = "yourcompany.app@gmail.com"
#     GMAIL_APP_PASSWORD = "xxxx xxxx xxxx xxxx"   # 16-char App Password
#     APP_BASE_URL       = "https://your-app-url.streamlit.app"
#
# How to get a Gmail App Password:
# 1. Enable 2-Step Verification on the Gmail account used to send mail.
# 2. Go to https://myaccount.google.com/apppasswords
# 3. Create an App Password for "Mail" and copy the 16-character code.
# 4. Use that code as GMAIL_APP_PASSWORD (NOT your normal Gmail password).
# =============================================================================
def _get_email_setting(key, default=""):
    try:
        if key in st.secrets:
            return str(st.secrets[key])
    except Exception:
        pass
    return os.environ.get(key, default)
GMAIL_ADDRESS = _get_email_setting("GMAIL_ADDRESS", "")
GMAIL_APP_PASSWORD = _get_email_setting("GMAIL_APP_PASSWORD", "")
APP_BASE_URL = _get_email_setting("APP_BASE_URL", "http://localhost:8501")
SMTP_HOST = "smtp.gmail.com"
SMTP_PORT = 587
def email_is_configured():
    return bool(GMAIL_ADDRESS) and bool(GMAIL_APP_PASSWORD)
def send_password_reset_email(to_email, to_name, reset_token):
    if not email_is_configured():
        return False, (
            "Email sending is not configured. Please set GMAIL_ADDRESS and "
            "GMAIL_APP_PASSWORD in Streamlit secrets or environment variables."
        )
    reset_link = f"{APP_BASE_URL}/?reset_token={reset_token}"
    subject = "Password Reset - INSIGHT System"
    body_text = f"""Hello {to_name},

We received a request to reset your password for the INSIGHT System.

Click the link below to set a new password. This link is valid for {RESET_TOKEN_VALID_MINUTES} minutes:

{reset_link}

If you did not request this, you can safely ignore this email; your password will not be changed.

Regards,
INSIGHT System
"""
    message = MIMEMultipart()
    message["From"] = GMAIL_ADDRESS
    message["To"] = to_email
    message["Subject"] = subject
    message.attach(MIMEText(body_text, "plain"))
    try:
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=20) as server:
            server.starttls()
            server.login(GMAIL_ADDRESS, GMAIL_APP_PASSWORD)
            server.sendmail(GMAIL_ADDRESS, to_email, message.as_string())
        return True, "Reset email sent."
    except Exception as error:
        return False, f"Failed to send reset email: {error}"
