# =============================================================================
# AUTHENTICATION (REGISTER / LOGIN WITH EMAIL + USERNAME) - SQLite + bcrypt
# =============================================================================
EMAIL_PATTERN = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
def hash_password(password):
    return bcrypt.hashpw(str(password).encode("utf-8"), bcrypt.gensalt()).decode("utf-8")
def verify_password(password, password_hash):
    try:
        return bcrypt.checkpw(str(password).encode("utf-8"), str(password_hash).encode("utf-8"))
    except Exception:
        return False
def is_valid_email(email):
    return bool(EMAIL_PATTERN.match(str(email).strip()))
def username_exists(username):
    return db_username_exists(username)
def email_exists(email):
    return db_email_exists(email)
def register_user(username, name, email, password, password_confirm):
    username = str(username).strip()
    name = str(name).strip()
    email = str(email).strip()
    if not username or not name or not email or not password:
        return False, "All fields are required."
    if not re.match(r"^[A-Za-z0-9_.-]+$", username):
        return False, "Username can only contain letters, numbers, dot, dash, and underscore."
    if not is_valid_email(email):
        return False, "Please enter a valid email address."
    if password != password_confirm:
        return False, "Password confirmation does not match."
    if len(str(password)) < 6:
        return False, "Password must be at least 6 characters long."
    if username_exists(username):
        return False, "Username already exists. Please choose another username."
    if email_exists(email):
        return False, "Email is already registered. Please log in instead."
    try:
        db_insert_user(
            username=username,
            name=name,
            email=email,
            password_hash=hash_password(password),
            created_at=app_now_text(),
        )
    except Exception as error:
        return False, f"Registration failed: {error}"
    return True, "Registration successful. You can now log in."
def authenticate_user(identifier, password):
    user = db_get_user_by_identifier(identifier)
    if user is None:
        return False, "", ""
    if verify_password(password, user["password_hash"]):
        return True, user["username"], user["name"]
    return False, "", ""
def request_password_reset(identifier):
    user = db_get_user_by_identifier(identifier)
    if user is None:
        # Do not reveal whether the identifier exists, to avoid user enumeration.
        return True, (
            "If an account with that username/email exists, a password reset link "
            "has been sent to the registered email."
        )
    token = secrets_lib.token_urlsafe(32)
    created_at = utc_now()
    expires_at = created_at + timedelta(minutes=RESET_TOKEN_VALID_MINUTES)
    db_create_reset_token(
        token=token,
        username=user["username"],
        created_at=created_at.isoformat(timespec="seconds"),
        expires_at=expires_at.isoformat(timespec="seconds"),
    )
    sent, message = send_password_reset_email(
        to_email=user["email"],
        to_name=user["name"],
        reset_token=token,
    )
    if not sent:
        return False, message
    return True, (
        "If an account with that username/email exists, a password reset link "
        "has been sent to the registered email."
    )
def validate_reset_token(token):
    record = db_get_reset_token(token)
    if record is None:
        return False, "Reset link is invalid.", None
    if record["used"]:
        return False, "This reset link has already been used.", None
    try:
        expires_at = datetime.fromisoformat(record["expires_at"])
    except (TypeError, ValueError):
        return False, "Reset link is invalid.", None
    # Historical tokens were stored without timezone; leave their old semantics in place.
    now_value = utc_now() if expires_at.tzinfo is not None else datetime.now()
    if now_value > expires_at:
        return False, "This reset link has expired. Please request a new one.", None
    return True, "Token valid.", record["username"]
def complete_password_reset(token, new_password, new_password_confirm):
    valid, message, username = validate_reset_token(token)
    if not valid:
        return False, message
    if not new_password:
        return False, "Password is required."
    if new_password != new_password_confirm:
        return False, "Password confirmation does not match."
    if len(str(new_password)) < 6:
        return False, "Password must be at least 6 characters long."
    db_update_password(username, hash_password(new_password))
    db_mark_token_used(token)
    db_invalidate_user_tokens(username)
    return True, "Password has been reset successfully. You can now log in with your new password."
