def load_history_for_user(username):
    raw_records = db_load_history_for_user(username)
    records = []
    for raw in raw_records:
        try:
            records.append(json.loads(raw))
        except Exception:
            continue
    return records
def append_history_record(username, record):
    db_insert_history_record(
        username=username,
        data_json=json.dumps(record, default=str),
        created_at=app_now_text(),
    )
def append_history_records(username, records):
    now_text = app_now_text()
    rows = [(username, json.dumps(record, default=str), now_text) for record in records]
    db_insert_history_records(rows)
def clear_history_for_user(username):
    db_delete_history_for_user(username)
