def parse_numeric_value(value):
    """Parse finite numbers consistently across OS locales.

    Text supports a decimal comma, decimal point, and mixed grouping (e.g.
    1.234,56 or 1,234.56). A lone comma is considered a decimal comma;
    for ambiguous inputs (e.g. 1,000), use a numeric Excel cell instead.
    Returns None for an absent or malformed value instead of silently using 0.
    """
    import math
    if value is None or isinstance(value, bool):
        return None
    try:
        if pd.isna(value):
            return None
    except (TypeError, ValueError):
        pass
    value_text = str(value).strip().replace("\u00a0", " ").replace("\u202f", " ")
    if not value_text or value_text.casefold() in EMPTY_VALUES:
        return None
    matched = re.fullmatch(
        r"\s*([+-]?(?:(?:\d[\d.,]*|\.\d+)(?:[eE][+-]?\d+)?))\s*"
        r"(?:ppm|kv|%|mg\s*koh/g|mn/m|dyne/cm)?\s*",
        value_text, flags=re.IGNORECASE,
    )
    if not matched:
        return None
    token = matched.group(1)
    exponent = ""
    exponent_match = re.search(r"[eE][+-]?\d+$", token)
    if exponent_match:
        exponent = exponent_match.group()
        token = token[:exponent_match.start()]
    if "." in token and "," in token:
        # Whichever separator appears last is the decimal mark.
        decimal_sep = "." if token.rfind(".") > token.rfind(",") else ","
        group_sep = "," if decimal_sep == "." else "."
        token = token.replace(group_sep, "")
        if decimal_sep == ",":
            token = token.replace(",", ".")
    elif "," in token:
        if token.count(",") > 1:
            pieces = token.split(",")
            if not all(len(p) == 3 for p in pieces[1:]):
                return None
            token = "".join(pieces)
        else:
            token = token.replace(",", ".")
    elif token.count(".") > 1:
        pieces = token.split(".")
        if not all(len(p) == 3 for p in pieces[1:]):
            return None
        token = "".join(pieces)
    try:
        num = float(token + exponent)
        return num if math.isfinite(num) else None
    except ValueError:
        return None


def to_number(value, default=0.0):
    parsed = parse_numeric_value(value)
    return default if parsed is None else parsed


def is_available(value):
    try:
        if value is None or pd.isna(value):
            return False
    except (TypeError, ValueError):
        pass
    return str(value).strip().casefold() not in EMPTY_VALUES


def is_numeric_available(value):
    return parse_numeric_value(value) is not None

def is_positive_number(value):
    return is_numeric_available(value) and to_number(value, 0) > 0

def valid_gas_values(values):
    """DGA inputs in ppm: all supplied values must be finite, numeric and nonnegative."""
    return all(is_numeric_available(v) and math.isfinite(to_number(v)) and to_number(v) >= 0 for v in values)


def validated_gases(values, context="DGA"):
    if not valid_gas_values(values):
        raise ValueError(f"{context}: seluruh gas harus numerik, >= 0 ppm, tanpa data kosong/NaN.")
    return [to_number(v) for v in values]


# Each INSIGHT assessment explicitly selects one of two independently configured
# Health Index calculation paths. The names and versions are stored with results.
ASSESSMENT_MODES = ("Capstone", "Skripsi")
CALCULATION_VERSION_DUAL = "INSIGHT-scientific-v7-CAPSTONE-NADERIAN-IEEE2019-DP1"

def normalize_assessment_mode(value):
    if value is None or str(value).strip() == "":
        return "Capstone"  # old records from V5.1 were the Capstone configuration
    label = str(value).strip().casefold()
    if label in ("skripsi", "thesis", "tugas akhir"):
        return "Skripsi"
    if label in ("capstone", "cd", "capstone design"):
        return "Capstone"
    raise ValueError("Mode analisis tidak dikenali: pilih Capstone atau Skripsi.")


def resolve_batch_assessment_mode(raw_mode, selected_mode):
    """Missing Excel mode (including NaN) inherits the web selection; bad values are rejected."""
    if not is_available(raw_mode):
        return normalize_assessment_mode(selected_mode)
    return normalize_assessment_mode(raw_mode)


def _weighted_oil_quality(scores):
    """Naderian (2009) oil scoring: each supplied score is graded 1..4."""
    weights = {"BDV":3, "Water Content":4, "IFT":2, "Acidity":1, "Color":2}
    if not all(name in scores for name in ("BDV", "Water Content")):
        raise ValueError("BDV dan Water Content diperlukan untuk OilQF.")
    for name, score in scores.items():
        if name not in weights or score not in (1,2,3,4):
            raise ValueError(f"Skor minyak tidak valid: {name}={score}.")
    num = sum(weights[name]*score for name, score in scores.items())
    den = sum(weights[name] for name in scores)
    return num / den, num, den


def calculate_hi_skripsi(score_bdv, score_wc, hif_dga):
    """THESIS: OilQF(BDV=3, WC=4) and 7-gas DGAF only; Naderian adapted weights.

    No IFT, acidity, color, furan, power-factor or load/loss contributions.
    For a full thesis HI, all seven gas readings are mandatory.
    """
    if hif_dga is None:
        raise ValueError("Mode Skripsi memerlukan 7 gas DGA valid untuk menghitung DGAF dan HI. "
                         "Data tidak lengkap tidak boleh diperlakukan sebagai skor sehat.")
    oqf, oil_score_sum, oil_weight_sum = _weighted_oil_quality({"BDV":score_bdv,"Water Content":score_wc})
    hif_oil = hif_from_factor(oqf)
    numerator = hif_oil*6 + hif_dga*10
    denominator = 6+10
    return {
        "oqf":oqf, "oil_score_total":oil_score_sum, "oil_weight_total":oil_weight_sum,
        "hif_oil":hif_oil, "total_score":numerator, "total_weight":denominator,
        "hi_percent":numerator/(4*denominator)*100,
        "coverage":"3/3 kelompok (BDV, WC, DGA)", "coverage_count":3, "coverage_total":3,
        "formula":"OQF=(3×S_BDV+4×S_WC)/7; HI=(6×HIF_Oil+10×HIF_DGA)/(4×16)×100%",
        "included":["BDV","Water Content","DGA"],
    }


def calculate_hi_capstone(score_bdv, score_wc, hif_dga=None, score_ift=None,
                           score_acidity=None, score_color=None, hif_furan=None,
                           hif_pf=None, loss_hif=None):
    """CAPSTONE: nine measured input groups, Naderian-style 5 scored factors.

    BDV/WC/IFT/Acidity/Color feed OilQF (one HIF factor). DGA, Furan,
    Power Factor and external Load/Loss HIF are separate weighted factors.
    Incomplete input is explicitly marked partial; missing is NEVER scored 4.
    This is an adaptation of Naderian 2009, not its complete 24-factor model.
    """
    oil_scores={"BDV":score_bdv,"Water Content":score_wc}
    for name,score in (("IFT",score_ift),("Acidity",score_acidity),("Color",score_color)):
        if score is not None: oil_scores[name]=score
    oqf, oil_score_sum, oil_weight_sum = _weighted_oil_quality(oil_scores)
    hif_oil=hif_from_factor(oqf)
    weighted={"Oil Quality":(hif_oil,6)}
    for name,factor,weight in (("DGA",hif_dga,10), ("Furan",hif_furan,5),
                               ("Power Factor",hif_pf,10), ("Load/Loss HIF",loss_hif,10)):
        if factor is not None:
            if not isinstance(factor,(int,float)) or not 0<=factor<=4:
                raise ValueError(f"HIF tidak valid untuk {name}: rentang 0 sampai 4.")
            weighted[name]=(factor,weight)
    num=sum(hif*w for hif,w in weighted.values())
    den=sum(w for hif,w in weighted.values())
    included=list(oil_scores)+[x for x in ("DGA","Furan","Power Factor","Load/Loss HIF") if x in weighted]
    count=len(included)
    return {
        "oqf":oqf, "oil_score_total":oil_score_sum, "oil_weight_total":oil_weight_sum,
        "hif_oil":hif_oil, "total_score":num, "total_weight":den,
        "hi_percent":num/(4*den)*100,
        "coverage":f"{count}/9 parameter" + (" (lengkap)" if count==9 else " (parsial)"),
        "coverage_count":count, "coverage_total":9,
        "formula":"OilQF=Σ(S_i×W_i)/ΣW_i; HI=Σ(HIF_j×K_j)/(4×ΣK_j)×100% (faktor tersedia)",
        "included":included,
    }


def overall_followup_priority(hi_category, dga_status, hi_complete=True,
                              duval_zone="", duval_method="Not Available"):
    """Readable, *indicative follow-up*, NOT a new Overall risk category.

    Safety-sensitive findings take precedence, missing Capstone inputs are
    disclosed, and a Duval fault zone cannot be silently treated as 'normal'.
    These are platform triage suggestions, not normative IEEE maintenance orders.
    """
    if dga_status == 3 or hi_category in ("Poor", "Very Poor"):
        return "Investigasi teknis diprioritaskan"
    if duval_method in ("DP1", "DT1") and duval_zone in ("PD", "D1", "D2", "T2", "T3", "DT"):
        return "Verifikasi indikasi gangguan Duval dan tinjau tren gas"
    if dga_status == 2 or hi_category == "Fair":
        return "Verifikasi dan tingkatkan pemantauan"
    if not hi_complete or dga_status not in (1, 2, 3):
        return "Evaluasi parsial: lengkapi dan konfirmasi data"
    if duval_method in ("DP1", "DT1") and duval_zone:
        return "Konfirmasi indikasi Duval terhadap riwayat dan kondisi operasi"
    return "Pemantauan sesuai kebijakan pemilik aset"

def duval_selection(available_dp1, available_dt1):
    """CD-3 selection hierarchy: exactly one method per assessment."""
    if available_dp1:
        return "DP1"
    if available_dt1:
        return "DT1"
    return "Not Available"

def normalize_bool(value):
    try:
        if value is None or pd.isna(value):
            return False
    except Exception:
        pass
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value != 0
    text = str(value).strip().lower()
    if text in ["true", "yes", "y", "1", "use", "used", "pakai", "dipakai"]:
        return True
    if text in ["false", "no", "n", "0", "not used", "tidak", "tidak dipakai"]:
        return False
    return bool(value)
def detect_dga_usage(gas_values, requested=True):
    if not normalize_bool(requested):
        return False, "DGA not selected."
    count = sum(is_numeric_available(v) for v in gas_values)
    if count != len(gas_values):
        return False, f"DGA not available: {count}/7 numeric gas values."
    if not valid_gas_values(gas_values):
        return False, "DGA not available: invalid/negative gas concentration."
    # Seven legitimate zero readings are valid for 2019 concentration screening.
    return True, "DGA available; IEEE 2019 level-based screening (delta/rates require serial samples)."
def normalize_condition_label(value):
    if not is_available(value):
        return ""
    text = re.sub(r"[^a-z0-9]+", "", str(value).strip().lower())
    mapping = {
        "verygood": "Very Good",
        "vg": "Very Good",
        "good": "Good",
        "fair": "Fair",
        "poor": "Poor",
        "verypoor": "Very Poor",
        "vp": "Very Poor",
        "sangatbaik": "Very Good",
        "baik": "Good",
        "cukup": "Fair",
        "sedang": "Fair",
        "kurang": "Poor",
        "buruk": "Poor",
        "sangatburuk": "Very Poor",
    }
    return mapping.get(text, str(value).strip())
def lifetime_from_condition(condition, fallback=""):
    if condition == "Very Good":
        return "> 15 years"
    if condition == "Good":
        return "> 10 years"
    if condition == "Fair":
        return "< 10 years"
    if condition == "Poor":
        return "< 3 years"
    if condition == "Very Poor":
        return "End-of-life"
    return fallback
def normalize_col_name(col):
    text = str(col).translate(SUBSCRIPT_TRANSLATION).strip().lower()
    text = text.replace("≤", "le").replace("≥", "ge")
    return re.sub(r"[^a-z0-9]+", "", text)
def get_col_value(row, col_map, names, default=""):
    for name in names:
        key = normalize_col_name(name)
        if key in col_map:
            return row[col_map[key]]
    return default
def make_unique_columns(columns):
    clean_columns = []
    seen = {}
    for idx, col in enumerate(columns):
        name = str(col).strip()
        if name.lower() in EMPTY_VALUES or name.lower().startswith("unnamed"):
            name = f"DropColumn_{idx}"
        if name in seen:
            seen[name] += 1
            name = f"{name}_{seen[name]}"
        else:
            seen[name] = 0
        clean_columns.append(name)
    return clean_columns
def read_excel_auto_header(uploaded_excel):
    uploaded_excel.seek(0)
    raw_df = pd.read_excel(uploaded_excel, header=None, engine="openpyxl")
    raw_df = raw_df.dropna(how="all")
    raw_df = raw_df.dropna(axis=1, how="all")
    header_idx = None
    for idx, row in raw_df.iterrows():
        normalized_values = [
            normalize_col_name(value)
            for value in row.tolist()
            if is_available(value)
        ]
        has_bdv = any(
            value in ["bdv", "breakdownvoltage", "dielectricstrength"]
            for value in normalized_values
        )
        has_wc = any(
            value in ["watercontent", "waterconten", "wc", "moisture"]
            for value in normalized_values
        )
        if has_bdv and has_wc:
            header_idx = idx
            break
    if header_idx is None:
        uploaded_excel.seek(0)
        fallback_df = pd.read_excel(uploaded_excel, engine="openpyxl")
        fallback_df = fallback_df.dropna(how="all").copy()
        fallback_df["_insight_excel_row"] = fallback_df.index.astype(int) + 2
        return fallback_df.reset_index(drop=True)
    header = raw_df.loc[header_idx].tolist()
    df = raw_df.loc[header_idx + 1:].copy()
    df.columns = make_unique_columns(header)
    df = df[
        [
            col for col in df.columns
            if not str(col).startswith("DropColumn_")
        ]
    ]
    df = df.dropna(how="all")
    # Physical Excel row numbers survive nonstandard header positions/blank rows.
    df["_insight_excel_row"] = df.index.astype(int) + 1
    df = df.reset_index(drop=True)
    return df
def normalize_voltage_class(value):
    text = str(value).strip().lower().replace(" ", "")
    if text in [
        "≤69kv",
        "<=69kv",
        "<69kv",
        "69",
        "69kv",
        "le69kv",
    ]:
        return "≤ 69 kV"
    if text in [
        "69kv-230kv",
        "69-230",
        "69kvto230kv",
        "69to230kv",
        "69kv230kv",
    ]:
        return "69 kV - 230 kV"
    if text in [
        "≥230kv",
        ">=230kv",
        ">230kv",
        "230",
        "230kv",
        "ge230kv",
    ]:
        return "≥ 230 kV"
    # General uploads often supply the nominal voltage as a number (e.g. 20 kV
    # or 150). Never silently treat a 150 kV transformer as the <=69 kV class.
    value_match = re.fullmatch(r"(\d+(?:[.,]\d+)?)(?:kv)?", text)
    if value_match:
        number = float(value_match.group(1).replace(",", "."))
        if number <= 0:
            raise ValueError("Kelas tegangan harus > 0 kV.")
        if number <= 69:
            return "≤ 69 kV"
        if number < 230:
            return "69 kV - 230 kV"
        return "≥ 230 kV"
    raise ValueError(f"Kelas tegangan '{value}' tidak dikenali. Isi kelas tegangan atau nominal dalam kV.")
def condition_badge(condition):
    if condition in ["Very Good", "Good"]:
        return f'<span class="badge-good">{condition}</span>'
    if condition == "Fair":
        return f'<span class="badge-fair">{condition}</span>'
    return f'<span class="badge-poor">{condition}</span>'
