def ternary_to_xy(a, b, c):
    total = a + b + c
    if total == 0:
        return 0, 0
    a = a / total
    b = b / total
    c = c / total
    x = 0.5 * a + b
    y = 0.8660254038 * a
    return x, y
def point_on_segment(point, start, end, tolerance=1e-9):
    px, py = point
    x1, y1 = start
    x2, y2 = end
    cross = (py - y1) * (x2 - x1) - (px - x1) * (y2 - y1)
    if abs(cross) > tolerance:
        return False
    dot = (px - x1) * (x2 - x1) + (py - y1) * (y2 - y1)
    if dot < -tolerance:
        return False
    length_squared = (x2 - x1) ** 2 + (y2 - y1) ** 2
    if dot - length_squared > tolerance:
        return False
    return True
def point_in_polygon(point, polygon):
    x, y = point
    inside = False
    j = len(polygon) - 1
    for i in range(len(polygon)):
        xi, yi = polygon[i]
        xj, yj = polygon[j]
        if point_on_segment(point, (xi, yi), (xj, yj)):
            return True
        intersects = ((yi > y) != (yj > y)) and (
            x < (xj - xi) * (y - yi) / ((yj - yi) if (yj - yi) != 0 else 1e-12) + xi
        )
        if intersects:
            inside = not inside
        j = i
    return inside
def classify_duval_zone(ch4_pct, c2h2_pct, c2h4_pct):
    point = ternary_to_xy(ch4_pct, c2h2_pct, c2h4_pct)
    for zone in ["PD", "D1", "D2", "T1", "T2", "T3", "DT"]:
        region = DUVAL_REGIONS[zone]
        polygon = [
            ternary_to_xy(a, b, c)
            for a, b, c in zip(region["a"], region["b"], region["c"])
        ]
        if point_in_polygon(point, polygon):
            return zone
    return "Unclassified"
def calculate_duval_result(ch4, c2h4, c2h2, use_duval):
    none_result = {
        "available": False, "zone": "Not Available", "fault_type": "DT1 data not sufficient or invalid",
        "ch4_pct": "", "c2h2_pct": "", "c2h4_pct": "",
    }
    if not use_duval or not valid_gas_values([ch4, c2h4, c2h2]):
        return none_result
    total = ch4 + c2h4 + c2h2
    if total <= 0:
        return dict(none_result, fault_type="DT1 normalization sum must be >0")
    ch4_pct = ch4 / total * 100
    c2h2_pct = c2h2 / total * 100
    c2h4_pct = c2h4 / total * 100
    zone = classify_duval_zone(ch4_pct, c2h2_pct, c2h4_pct)
    return {
        "available": True,
        "zone": zone,
        "fault_type": DUVAL_FAULT_TYPE.get(zone, "Unclassified Duval Triangle zone"),
        "ch4_pct": ch4_pct, "c2h2_pct": c2h2_pct, "c2h4_pct": c2h4_pct,
    }
