def classify_duval_pentagon_zone(x, y):
    if not (math.isfinite(x) and math.isfinite(y)):
        return "Unclassified"
    hits = [name for name, corners in DUVAL_PENTAGON_1_ZONES.items()
            if point_in_polygon((x,y), corners)]
    if len(hits) == 1:
        return hits[0]
    if len(hits) > 1:
        return "Boundary (" + "/".join(hits) + ")"
    return "Unclassified"

def polygon_centroid(points):
    area = 0.0
    centroid_x = 0.0
    centroid_y = 0.0
    total_points = len(points)
    for i in range(total_points):
        x1, y1 = points[i]
        x2, y2 = points[(i + 1) % total_points]
        cross = x1 * y2 - x2 * y1
        area += cross
        centroid_x += (x1 + x2) * cross
        centroid_y += (y1 + y2) * cross
    area = area / 2.0
    if abs(area) < 1e-12:
        avg_x = sum(point[0] for point in points) / total_points
        avg_y = sum(point[1] for point in points) / total_points
        return avg_x, avg_y
    centroid_x = centroid_x / (6.0 * area)
    centroid_y = centroid_y / (6.0 * area)
    return centroid_x, centroid_y
def calculate_duval_pentagon_result(h2, ch4, c2h6, c2h4, c2h2, use_pentagon):
    none_result = {
        "available": False, "zone": "Not Available", "fault_type": "DP1 data not sufficient or invalid",
        "dominant_gas": "Not Available", "pattern": "Required Duval Pentagon gases are unavailable",
        "centroid_x": "", "centroid_y": "", "h2_pct": "", "ch4_pct": "", "c2h6_pct": "",
        "c2h4_pct": "", "c2h2_pct": "", "polygon_points": [],
    }
    values = [h2,ch4,c2h6,c2h4,c2h2]
    if not use_pentagon or not valid_gas_values(values):
        return none_result
    total = sum(values)
    if total <= 0:
        return dict(none_result, fault_type="DP1 normalization sum must be >0")
    percentages = {"H2":h2/total*100, "C2H6":c2h6/total*100, "CH4":ch4/total*100,
                   "C2H4":c2h4/total*100, "C2H2":c2h2/total*100}
    polygon_points = [(PENTAGON_FULL_VERTICES[gas][0] * percentages[gas]/100,
                       PENTAGON_FULL_VERTICES[gas][1] * percentages[gas]/100)
                      for gas in PENTAGON_GAS_ORDER]
    twice_area = sum(x1*y2-x2*y1 for (x1,y1),(x2,y2)
                     in zip(polygon_points, polygon_points[1:]+polygon_points[:1]))
    if abs(twice_area) < 1e-10:
        return dict(none_result, fault_type="DP1 polygon has zero area; cannot classify")
    cx,cy = polygon_centroid(polygon_points)
    zone = classify_duval_pentagon_zone(cx,cy)
    dominant = max(percentages,key=percentages.get)
    return {
        "available":True, "zone":zone,
        "fault_type":PENTAGON_FAULT_TYPES.get(zone,"At DP1 zone boundary or unclassified; technical review needed"),
        "dominant_gas":dominant,
        "pattern":PENTAGON_PATTERN_DESCRIPTION.get(dominant,""),
        "centroid_x":cx,"centroid_y":cy,
        "h2_pct":percentages["H2"],"ch4_pct":percentages["CH4"],
        "c2h6_pct":percentages["C2H6"],"c2h4_pct":percentages["C2H4"],
        "c2h2_pct":percentages["C2H2"],"polygon_points":polygon_points,
    }

def selected_duval_results_from_record(record):
    """Rebuild only selected diagnosis for v5; never reinterpret legacy results silently."""
    record=record or {}
    meth=str(record.get("Duval Method","")).strip().upper()
    if meth not in ("DP1","DT1"):
        return ({"available":False}, {"available":False})
    gas=lambda key:record.get(key, "")
    if meth=="DP1":
        return ({"available":False},calculate_duval_pentagon_result(
            gas("H2"),gas("CH4"),gas("C2H6"),gas("C2H4"),gas("C2H2"),True))
    return (calculate_duval_result(gas("CH4"),gas("C2H4"),gas("C2H2"),True),{"available":False})

