def get_all_reference_limits():
    rows = []
    for voltage_class in ["≤ 69 kV", "69 kV - 230 kV", "≥ 230 kV"]:
        for row in get_reference_limits(voltage_class):
            copied = row.copy()
            copied["Voltage Class"] = voltage_class
            rows.append(copied)
    return pd.DataFrame(rows)
