def gas_score(value, limits):
    if value <= limits[0]:
        return 1
    if value <= limits[1]:
        return 2
    if value <= limits[2]:
        return 3
    if value <= limits[3]:
        return 4
    if value <= limits[4]:
        return 5
    return 6
def hif_from_factor(factor):
    if factor < 1.2:
        return 4
    if factor < 1.5:
        return 3
    if factor < 2:
        return 2
    if factor < 3:
        return 1
    return 0
def hi_condition(hi_percent):
    if hi_percent >= 85:
        return "Very Good", "> 15 years"
    if hi_percent >= 70:
        return "Good", "> 10 years"
    if hi_percent >= 50:
        return "Fair", "< 10 years"
    if hi_percent >= 30:
        return "Poor", "< 3 years"
    return "Very Poor", "End-of-life"
def dga_indication(h2, ch4, co, co2, c2h4, c2h6, c2h2):
    if c2h2 > 35:
        return "Arcing"
    if h2 > 100 and (ch4 > 120 or c2h6 > 65 or c2h4 > 50):
        return "Partial Discharge + Thermal Fault"
    if h2 > 100:
        return "Partial Discharge"
    if c2h4 > 50:
        return "High-Temperature Thermal Fault"
    if ch4 > 120 or c2h6 > 65:
        return "Low-to-Medium Temperature Thermal Fault"
    if co > 350 or co2 > 2500:
        return "Cellulose Degradation Indication"
    return "Normal DGA"

# IEEE C57.104-2019 Tables 1–4, PDF pages 39–40.
# Unknown-age, O2/N2>0.2 is REQUIRED default when no age and O2/N2 data are provided.
IEEE2019_LEVELS = {
    "o2_high_unknown": {
        "t1":{"H2":40,"CH4":20,"C2H6":15,"C2H4":50,"C2H2":2,"CO":500,"CO2":5000},
        "t2":{"H2":90,"CH4":50,"C2H6":40,"C2H4":100,"C2H2":7,"CO":600,"CO2":7000},
        "delta":{"H2":25,"CH4":10,"C2H6":7,"C2H4":20,"C2H2":0,"CO":175,"CO2":1750},
    },
    "o2_low_unknown": {
        "t1":{"H2":80,"CH4":90,"C2H6":90,"C2H4":50,"C2H2":1,"CO":900,"CO2":9000},
        "t2":{"H2":200,"CH4":150,"C2H6":175,"C2H4":100,"C2H2":2,"CO":1100,"CO2":12500},
        "delta":{"H2":40,"CH4":30,"C2H6":25,"C2H4":20,"C2H2":0,"CO":250,"CO2":2500},
    },
}
# Table 4: gas generation in ppm/year from linear regression, 3–6 samples over 4–24 months.
IEEE2019_RATES = {
    ("o2_high_unknown", "4-9"):{"H2":25,"CH4":4,"C2H6":3,"C2H4":7,"C2H2":0,"CO":100,"CO2":1000},
    ("o2_high_unknown", "10-24"):{"H2":10,"CH4":3,"C2H6":2,"C2H4":5,"C2H2":0,"CO":80,"CO2":800},
    ("o2_low_unknown", "4-9"):{"H2":50,"CH4":15,"C2H6":15,"C2H4":10,"C2H2":0,"CO":200,"CO2":1750},
    ("o2_low_unknown", "10-24"):{"H2":20,"CH4":10,"C2H6":9,"C2H4":7,"C2H2":0,"CO":100,"CO2":1000},
}
IEEE2019_GAS_NAMES = ("H2", "CH4", "C2H6", "C2H4", "C2H2", "CO", "CO2")


def ieee_dga_status_2019(gases, o2_n2_ratio=None, transformer_age=None,
                         previous_gases=None, series=None, confirmed=False):
    """IEEE 2019 DGA status 1/2/3 screening; never equate status with transformer condition.

    Unknown age uses the Unknown column. If an age is supplied without configured
    age-specific norms, fail rather than silently use the wrong column.
    A positive delta needs a confirmation sample; the status is explicitly provisional.
    """
    if transformer_age is not None:
        raise ValueError("Age-specific IEEE 2019 norm table not configured: do not assume unknown-age norms")
    if o2_n2_ratio is not None and (not isinstance(o2_n2_ratio,(float,int)) or
                                   not math.isfinite(o2_n2_ratio) or o2_n2_ratio < 0):
        raise ValueError("Invalid O2/N2 ratio")
    key = "o2_low_unknown" if o2_n2_ratio is not None and o2_n2_ratio <= .2 else "o2_high_unknown"
    norm=IEEE2019_LEVELS[key]
    vals=validated_gases([gases.get(n) for n in IEEE2019_GAS_NAMES], "IEEE DGA")
    current=dict(zip(IEEE2019_GAS_NAMES,vals))
    high=[n for n in IEEE2019_GAS_NAMES if current[n] >= norm["t2"][n]]
    elevated=[n for n in IEEE2019_GAS_NAMES if current[n] >= norm["t1"][n]]
    status=3 if high else (2 if elevated else 1)
    delta_flags=[]
    if previous_gases is not None:
        prior=validated_gases([previous_gases.get(n) for n in IEEE2019_GAS_NAMES],"Previous DGA")
        delta_flags=[n for n,p in zip(IEEE2019_GAS_NAMES,prior)
                     if current[n]-p > norm["delta"][n]]
        if delta_flags and not confirmed:
            status=max(2,status)  # suspected increase: prompt confirmation, not final judgment
    rate_flags=[]
    if series is not None:
        from datetime import datetime as _datetime
        rows=[]
        for sample in series:
            when=sample.get("Time")
            date = when if isinstance(when,_datetime) else _datetime.fromisoformat(str(when))
            sampled = validated_gases([sample.get(n) for n in IEEE2019_GAS_NAMES],"DGA sample")
            rows.append((date,dict(zip(IEEE2019_GAS_NAMES,sampled))))
        rows.sort(key=lambda pair:pair[0])
        rows=rows[-6:]
        if len(rows)>=3:
            span=(rows[-1][0]-rows[0][0]).total_seconds()/86400/30.4375
            if 4<=span<=24 and all(t[0]!=rows[0][0] for t in rows[1:]):
                period="4-9" if span<10 else "10-24"
                limit=IEEE2019_RATES[(key,period)]
                xs=[(t[0]-rows[0][0]).total_seconds()/86400/365.2425 for t in rows]
                xmean=sum(xs)/len(xs)
                den=sum((v-xmean)**2 for v in xs)
                if den>0:
                    for gas in IEEE2019_GAS_NAMES:
                        ys=[t[1][gas] for t in rows]
                        ym=sum(ys)/len(ys)
                        slope=sum((x-xmean)*(y-ym) for x,y in zip(xs,ys))/den
                        if slope>limit[gas]: rate_flags.append(gas)
                    if rate_flags: status=3
    return {
        "status":status, "norm_basis":"IEEE C57.104-2019, age unknown, O2/N2 " + ("<=0.2" if key=="o2_low_unknown" else ">0.2/default"),
        "provisional": not confirmed, "elevated_gases":elevated, "high_gases":high,
        "delta_exceeded":delta_flags, "rate_exceeded":rate_flags,
        "note":"Single DGA screening only; delta/rate and confirmation are unavailable" if previous_gases is None and series is None else
               ("Abnormal delta: obtain a confirmation sample" if delta_flags and not confirmed else "DGA status based on available sample history"),
    }

# =============================================================================
# IEEE C57.104-2019 STATUS (historical field name kept for old UI)
# =============================================================================
def ieee_tdcg_condition(h2, ch4, c2h2, c2h4, c2h6, co, co2, tdcg=None):
    """Compatibility shim for existing UI: returns 2019 DGA Status, NOT 1991/2008 TDCG class."""
    return ieee_dga_status_2019({"H2":h2,"CH4":ch4,"C2H6":c2h6,"C2H4":c2h4,
                                  "C2H2":c2h2,"CO":co,"CO2":co2})["status"]
def ieee_condition_action(condition):
    """IEEE C57.104-2019 6.1.2: qualitative guidance, not prescribed sampling intervals."""
    actions={
        1:("Continue routine operation and sampling according to owner/manufacturer policy.","Low"),
        2:("Investigate possible gas generation, confirm with a repeat sample, and increase surveillance when indicated.","Medium"),
        3:("Investigate promptly, consider increased surveillance/online monitoring and specialist consultation; assess operating precautions.","High"),
    }
    return actions.get(condition, ("DGA status unavailable; confirm data and sampling history.","Unknown"))
def get_recommendation(condition, dominant, severity="Normal", ieee_condition=None,
                       duval_zone="", duval_method=""):
    """Source-traceable advice collected from HI, DGA, and ONE Duval interpretation.

    These are preliminary maintenance directions, not a new index, forced
    outage instruction, or a claim that Duval by itself proves a defect.
    """
    advice=[]
    if condition in ("Very Good","Good"):
        advice.append(f"HI {condition}: lanjutkan pemantauan berkala berbasis kondisi aset")
    elif condition=="Fair":
        advice.append("HI Fair: evaluasi parameter yang menurunkan kesehatan, lakukan pengujian lanjutan sesuai kebutuhan")
    elif condition in ("Poor","Very Poor"):
        advice.append(f"HI {condition}: prioritaskan pemeriksaan kualitas minyak/isolasi dan rencanakan tindakan pemeliharaan")
    if ieee_condition==1:
        advice.append("DGA Status 1 (skrining): pertahankan jadwal pemantauan dan periksa tren bila ada")
    elif ieee_condition==2:
        advice.append("DGA Status 2 (skrining): konfirmasi hasil, telaah riwayat gas dan tingkatkan pengawasan bila perlu")
    elif ieee_condition==3:
        advice.append("DGA Status 3 (skrining): lakukan investigasi terarah sesegera mungkin dengan tenaga teknis, periksa tren dan kondisi operasi")
    zone_hints={
        "PD":"tinjau kemungkinan pelepasan sebagian dan konfirmasi dengan pengujian listrik yang relevan",
        "D1":"telaah indikasi pelepasan energi rendah; verifikasi tren gas dan kondisi isolasi",
        "D2":"telaah indikasi pelepasan energi tinggi; lakukan investigasi teknis dan pemeriksaan pengaman",
        "T1":"telaah indikasi pemanasan bersuhu rendah; periksa pembebanan dan sistem pendinginan",
        "T2":"telaah indikasi pemanasan menengah; evaluasi pembebanan, sambungan, dan pendinginan",
        "T3":"telaah indikasi pemanasan tinggi; prioritaskan investigasi sumber panas dan risiko internal",
        "DT":"telaah kemungkinan campuran indikasi termal dan listrik; butuh evaluasi lanjutan",
        "S":"telaah kemungkinan stray gassing minyak dan konfirmasi terhadap tren/riwayat",
    }
    if duval_method in ("DT1","DP1") and duval_zone in zone_hints:
        advice.append(f"{duval_method} zona {duval_zone}: {zone_hints[duval_zone]}; "
                      "zona Duval adalah indikasi jenis gangguan, bukan bukti kerusakan definitif")
    if dominant and dominant not in ("Normal","Not Available","DGA"):
        advice.append(f"Periksa parameter pembatas utama yang tercatat: {dominant}")
    if not advice:
        return "Hasil evaluasi belum mencukupi untuk rekomendasi lengkap; lengkapi dan validasi data pengujian."
    return "; ".join(advice)+". Keputusan operasi dan tindakan lapangan memerlukan pertimbangan teknisi berwenang."

def compose_overall_condition(hi_percent, hi_condition, dga_status=None,
                              duval_method="Not Available", duval_zone="",
                              duval_fault=""):
    """Integrate method outputs *descriptively*, without inventing HI/DGA/DP1 weights.

    The combined string is a multi-indicator assessment, not a newly validated
    ordinal Overall Condition category. Missing method outputs remain visible.
    """
    hi_label = str(hi_condition or "Not Available").strip()
    try:
        hi_value = f"{float(hi_percent):.1f}%"
    except (TypeError, ValueError):
        hi_value = "not available"

    try:
        dga_value = int(dga_status) if dga_status is not None else None
    except (ValueError, TypeError):
        dga_value = None
    if dga_value not in (1, 2, 3):
        dga_value = None

    method = str(duval_method or "").upper().strip()
    zone = str(duval_zone or "").strip()
    available_duval = method in ("DT1", "DP1") and zone and zone not in ("Not Available", "Unclassified")
    # Boundary classification is still useful evidence and not a fabricated fault type.
    if available_duval:
        duval_piece = f"{method} {zone}"
        duval_text = f"{method} zona {zone}"
        if duval_fault and str(duval_fault).strip() not in ("", "Not Available"):
            duval_text += f" ({duval_fault})"
    else:
        duval_piece = "Duval —"
        duval_text = "diagnosis Duval belum tersedia"

    status_piece = f"DGA S{dga_value}" if dga_value else "DGA —"
    label = " | ".join((f"HI {hi_label}", status_piece, duval_piece))
    available_count = 1 + int(dga_value is not None) + int(bool(available_duval))
    completeness = "Lengkap (HI, DGA, Duval)" if available_count == 3 else f"Parsial ({available_count}/3 keluaran)"
    dga_text = (f"DGA Status {dga_value} (skrining konsentrasi gas; belum termasuk konfirmasi tren)"
                if dga_value else "DGA Status belum tersedia")
    explanation = (
        f"Penilaian terpadu: indeks kesehatan {hi_value} ({hi_label}); "
        f"{dga_text}; {duval_text}. "
        "Setiap indikator dan rekomendasi metode dibaca bersama untuk evaluasi teknis. "
        "Ini adalah sintesis deskriptif, bukan skor gabungan, kategori risiko baru, "
        "atau diagnosis kegagalan yang telah dipastikan."
    )
    return label, completeness, explanation


def score_bdv_value(bdv, voltage_class):
    if voltage_class == "≤ 69 kV":
        if bdv >= 45:
            return 1
        if bdv >= 35:
            return 2
        if bdv >= 30:
            return 3
        return 4
    if voltage_class == "69 kV - 230 kV":
        if bdv >= 52:
            return 1
        if bdv >= 47:
            return 2
        if bdv >= 35:
            return 3
        return 4
    if bdv >= 60:
        return 1
    if bdv >= 50:
        return 2
    if bdv >= 40:
        return 3
    return 4
def score_wc_value(wc, voltage_class):
    if voltage_class == "≤ 69 kV":
        if wc <= 30:
            return 1
        if wc <= 35:
            return 2
        if wc <= 40:
            return 3
        return 4
    if voltage_class == "69 kV - 230 kV":
        if wc <= 20:
            return 1
        if wc <= 25:
            return 2
        if wc <= 30:
            return 3
        return 4
    if wc <= 15:
        return 1
    if wc <= 20:
        return 2
    if wc <= 25:
        return 3
    return 4
def oil_score_ift(value, voltage_class):
    if voltage_class == "≤ 69 kV":
        if value >= 25:
            return 1
        if value >= 20:
            return 2
        if value >= 15:
            return 3
        return 4
    if voltage_class == "69 kV - 230 kV":
        if value >= 30:
            return 1
        if value >= 23:
            return 2
        if value >= 18:
            return 3
        return 4
    if value >= 32:
        return 1
    if value >= 25:
        return 2
    if value >= 20:
        return 3
    return 4
def oil_score_acidity(value, voltage_class):
    if voltage_class == "≤ 69 kV":
        if value <= 0.05:
            return 1
        if value <= 0.10:
            return 2
        if value <= 0.20:
            return 3
        return 4
    if voltage_class == "69 kV - 230 kV":
        if value <= 0.04:
            return 1
        if value <= 0.10:
            return 2
        if value <= 0.15:
            return 3
        return 4
    if value <= 0.03:
        return 1
    if value <= 0.07:
        return 2
    if value <= 0.10:
        return 3
    return 4
def oil_score_color(value):
    if value <= 1.5:
        return 1
    if value <= 2.0:
        return 2
    if value <= 2.5:
        return 3
    return 4
def furan_hif(value):
    if value <= 0.1:
        return 4
    if value <= 0.25:
        return 3
    if value <= 0.5:
        return 2
    if value <= 1.0:
        return 1
    return 0
def pf_hif(value):
    if value < 0.5:
        return 4
    if value < 0.7:
        return 3
    if value < 1:
        return 2
    if value < 2:
        return 1
    return 0
def assessment_confidence(use_dga, use_ift, use_acidity, use_color, use_furan, use_pf, use_loss):
    optional_count = sum([use_ift, use_acidity, use_color, use_furan, use_pf, use_loss])
    if use_dga and optional_count >= 4:
        return (
            "Extended Assessment",
            "High",
            "Core parameters are available and supported by several additional diagnostic parameters.",
        )
    if use_dga and optional_count >= 1:
        return (
            "Enhanced Core Assessment",
            "High",
            "Core parameters are available and supported by additional diagnostic parameters.",
        )
    if use_dga:
        return (
            "Core Assessment",
            "Medium",
            "The assessment uses the main parameters: DGA, BDV, and water content.",
        )
    if optional_count >= 1:
        return (
            "Oil Quality + Supporting Assessment",
            "Medium",
            "DGA data are not available, so the assessment is based on BDV, water content, and supporting parameters.",
        )
    return (
        "Basic Oil Quality Assessment",
        "Low-Medium",
        "DGA data are not available, so the assessment is based only on BDV and water content.",
    )
def smart_explanation(condition, indication, dominant, score_bdv, score_wc, use_dga):
    if not use_dga and (score_bdv >= 3 or score_wc >= 3):
        return (
            "DGA data are not available. The analysis focuses on oil quality parameters. "
            "BDV and/or water content indicate a decrease in insulating oil quality."
        )
    if use_dga and indication == "Normal DGA" and (score_bdv >= 3 or score_wc >= 3):
        return (
            "DGA indicates normal gas conditions, but BDV and/or water content show "
            "a decrease in insulating oil quality."
        )
    if use_dga and indication != "Normal DGA" and dominant == "DGA":
        return (
            f"DGA indicates {indication}. The dissolved gas condition should be further evaluated "
            "and compared with previous testing trends."
        )
    if dominant == "BDV + Water Content":
        return (
            "BDV and water content simultaneously indicate oil quality degradation. "
            "This condition may reduce the dielectric strength of the insulating oil."
        )
    if dominant == "BDV":
        return (
            "BDV indicates a decrease in the dielectric strength of the insulating oil. "
            "Contamination, particles, or moisture in the oil should be evaluated."
        )
    if dominant == "Water Content":
        return (
            "Water content indicates a moisture level that requires attention. "
            "High moisture content may accelerate insulation degradation and reduce BDV."
        )
    if dominant == "Optional Oil Quality":
        return (
            "Additional oil quality parameters such as IFT, acidity, or color indicate "
            "possible oil degradation."
        )
    if dominant == "Furan":
        return "Furan indicates possible degradation of paper/cellulose insulation."
    if dominant == "Power Factor":
        return "Power factor indicates possible insulation degradation and increased dielectric loss."
    if condition in ["Very Good", "Good"]:
        return "Overall, the transformer condition is still acceptable based on the available parameters."
    return "The transformer condition requires attention based on the Health Index result."
def get_severity_rank(severity):
    rank = {
        "Normal": 0,
        "Low": 1,
        "Low-Medium": 2,
        "Medium": 3,
        "High": 4,
        "Critical": 5,
    }
    return rank.get(severity, 0)
def get_highest_severity(abnormal_df):
    if abnormal_df.empty or "Severity" not in abnormal_df.columns:
        return "Normal"
    severities = abnormal_df["Severity"].astype(str).tolist()
    return max(severities, key=get_severity_rank)
def make_abnormal_detail(
    use_dga,
    h2,
    ch4,
    co,
    co2,
    c2h4,
    c2h6,
    c2h2,
    bdv,
    wc,
    voltage_class,
    score_bdv,
    score_wc,
    use_ift,
    ift,
    score_ift,
    use_acidity,
    acidity,
    score_acidity,
    use_color,
    color,
    score_color,
    use_furan,
    furan,
    hif_furan,
    use_pf,
    pf,
    hif_pf,
):
    abnormal = []
    if use_dga:
        dga_checks = [
            (
                "H2",
                h2,
                100,
                "partial discharge",
                "Repeat DGA monitoring, evaluate H2 trend, and check possible partial discharge based on the transformer operating condition.",
                "Medium",
            ),
            (
                "CH4",
                ch4,
                120,
                "low-to-medium temperature thermal fault",
                "Evaluate possible low-level overheating, loading condition, internal connection condition, and methane gas trend.",
                "Medium",
            ),
            (
                "C2H6",
                c2h6,
                65,
                "low-to-medium temperature thermal fault",
                "Evaluate possible low-level overheating, loading condition, cooling system performance, and ethane gas trend.",
                "Medium",
            ),
            (
                "C2H4",
                c2h4,
                50,
                "high-temperature thermal fault",
                "Evaluate operating temperature, loading condition, cooling system, possible hot spot, and repeat DGA to confirm the trend.",
                "High",
            ),
            (
                "C2H2",
                c2h2,
                35,
                "arcing",
                "Prioritize further investigation because there is an indication of electrical fault/arcing. Retesting and internal transformer condition evaluation are recommended.",
                "Critical",
            ),
            (
                "CO",
                co,
                350,
                "cellulose/paper insulation degradation",
                "Evaluate paper insulation condition and correlate it with CO2, furan/2-FAL, operating temperature, and loading history.",
                "Medium",
            ),
            (
                "CO2",
                co2,
                2500,
                "cellulose/paper insulation degradation",
                "Evaluate paper insulation condition and CO2 trend over time. Correlate it with CO, furan, and temperature/loading history.",
                "Medium",
            ),
        ]
        for param, value, limit, meaning, action, severity in dga_checks:
            if value > limit:
                abnormal.append(
                    {
                        "Parameter": param,
                        "Measured Value": value,
                        "Reference Limit": f"> {limit} ppm",
                        "Condition Detail": (
                            f"{param} is elevated. The measured value of {param} = {value:.2f} ppm "
                            f"exceeds the initial threshold of {limit} ppm, indicating {meaning}."
                        ),
                        "Severity": severity,
                        "Action Required": action,
                        "Reference": "IEC 60599 / DGA interpretation approach",
                    }
                )
    if score_bdv >= 3:
        abnormal.append(
            {
                "Parameter": "BDV",
                "Measured Value": bdv,
                "Reference Limit": get_bdv_limit_text(voltage_class),
                "Condition Detail": (
                    f"BDV is low. The measured BDV = {bdv:.2f} kV indicates "
                    "a reduction in the dielectric strength of the insulating oil."
                ),
                "Severity": "High" if score_bdv == 4 else "Medium",
                "Action Required": (
                    "Repeat the BDV test according to IEC 60156. Evaluate contamination, particles, "
                    "and moisture. For in-service oil, use IEC 60422 as the maintenance assessment reference. "
                    "Oil filtration or purification should be considered if required."
                ),
                "Reference": "IEC 60156 / IEC 60422 / IEC 60296",
            }
        )
    if score_wc >= 3:
        abnormal.append(
            {
                "Parameter": "Water Content",
                "Measured Value": wc,
                "Reference Limit": get_wc_limit_text(voltage_class),
                "Condition Detail": (
                    f"Water content is high. The measured water content = {wc:.2f} ppm "
                    "may reduce the insulating capability of the oil."
                ),
                "Severity": "High" if score_wc == 4 else "Medium",
                "Action Required": (
                    "Verify water content using the IEC 60814 test method. Evaluate moisture source, "
                    "breather condition, sealing condition, and consider oil dehydration if required."
                ),
                "Reference": "IEC 60814 / IEC 60422 / IEC 60296",
            }
        )
    if use_ift and score_ift is not None and score_ift >= 3:
        abnormal.append(
            {
                "Parameter": "IFT",
                "Measured Value": ift,
                "Reference Limit": get_ift_limit_text(voltage_class),
                "Condition Detail": (
                    f"IFT is low. The measured IFT = {ift:.2f} dyne/cm indicates "
                    "possible oil contamination or oxidation."
                ),
                "Severity": "Medium",
                "Action Required": (
                    "Evaluate oil quality, correlate it with acidity and color, and consider oil treatment "
                    "or reclaiming if the degradation trend continues."
                ),
                "Reference": "IEC 60422 / oil quality assessment approach",
            }
        )
    if use_acidity and score_acidity is not None and score_acidity >= 3:
        abnormal.append(
            {
                "Parameter": "Acidity",
                "Measured Value": acidity,
                "Reference Limit": get_acidity_limit_text(voltage_class),
                "Condition Detail": (
                    f"Acidity is high. The measured acidity = {acidity:.3f} "
                    "indicates oil aging or oxidation."
                ),
                "Severity": "Medium",
                "Action Required": (
                    "Evaluate oil condition and correlate acidity with IFT and color. Oil treatment should be "
                    "considered if acidity increases along with decreasing IFT."
                ),
                "Reference": "IEC 60422 / oil quality assessment approach",
            }
        )
    if use_color and score_color is not None and score_color >= 3:
        abnormal.append(
            {
                "Parameter": "Color",
                "Measured Value": color,
                "Reference Limit": "≤1.5 Good; 1.6–2.0 Caution; 2.1–2.5 Poor; >2.5 Very Poor",
                "Condition Detail": (
                    f"Color has increased. The measured color = {color:.2f} indicates "
                    "visual changes related to oil degradation."
                ),
                "Severity": "Low-Medium",
                "Action Required": "Correlate the result with acidity, IFT, visual inspection, and other oil test results.",
                "Reference": "IEC 60422 / oil quality assessment approach",
            }
        )
    if use_furan and hif_furan is not None and hif_furan <= 2:
        abnormal.append(
            {
                "Parameter": "Furan",
                "Measured Value": furan,
                "Reference Limit": "≤0.1 Good; 0.11–0.25 Caution; 0.26–0.5 Need Attention; 0.51–1.0 Poor; >1.0 Very Poor",
                "Condition Detail": (
                    f"Furan is elevated. The measured furan = {furan:.3f} ppm "
                    "indicates possible paper/cellulose insulation degradation."
                ),
                "Severity": "High" if hif_furan <= 1 else "Medium",
                "Action Required": (
                    "Evaluate paper insulation aging and correlate it with CO/CO2, operating temperature, "
                    "and loading history."
                ),
                "Reference": "IEC 61198 / furan compound test method",
            }
        )
    if use_pf and hif_pf is not None and hif_pf <= 2:
        abnormal.append(
            {
                "Parameter": "Power Factor",
                "Measured Value": pf,
                "Reference Limit": "<0.5 Good; 0.5–0.69 Caution; 0.7–0.99 Need Attention; 1–1.99 Poor; ≥2 Very Poor",
                "Condition Detail": (
                    f"Power factor is elevated. The measured PF = {pf:.3f}% indicates "
                    "dielectric loss or insulation quality degradation."
                ),
                "Severity": "High" if hif_pf <= 1 else "Medium",
                "Action Required": "Perform insulation power factor/tan delta evaluation and inspect the insulation system.",
                "Reference": "IEC 60422 / dielectric loss assessment approach",
            }
        )
    if not abnormal:
        abnormal.append(
            {
                "Parameter": "Normal",
                "Measured Value": "-",
                "Reference Limit": "-",
                "Condition Detail": "No dominant parameter exceeds the attention threshold based on the available data.",
                "Severity": "Normal",
                "Action Required": "Continue routine monitoring according to the company maintenance schedule.",
                "Reference": "Assessment result",
            }
        )
    abnormal_df = pd.DataFrame(abnormal)
    abnormal_parameter = ", ".join(abnormal_df["Parameter"].astype(str).tolist())
    abnormal_detail = " | ".join(abnormal_df["Condition Detail"].astype(str).tolist())
    action_required = " | ".join(abnormal_df["Action Required"].astype(str).tolist())
    reference_limit = " | ".join(abnormal_df["Reference Limit"].astype(str).tolist())
    severity = get_highest_severity(abnormal_df)
    return abnormal_df, abnormal_parameter, abnormal_detail, action_required, reference_limit, severity

