def prepare_history_for_report(history_df):
    df = history_df.copy()
    required_cols = [
        "Username",
        "Time",
        "Analysis Mode", "HI Input Coverage", "HI Formula", "HI Included Parameters",
        "OilQF", "DGAF", "Overall Follow-up", "O2/N2 Ratio",
        "Transformer No",
        "Capacity",
        "Voltage Class",
        "BDV",
        "Water Content",
        "HI (%)",
        "Overall Condition",
        "Overall Condition Status",
        "Overall Condition Explanation",
        "Calculated Condition",
        "Calculated Lifetime",
        "Source Label",
        "Label Check",
        "Data Quality Note",
        "Duval Data Note",
        "Pentagon Data Note",
        "Expected Lifetime",
        "DGA Indication",
        "IEEE TDCG Condition", "DGA Status 2019", "DGA Screening Note",
        "Duval Method", "Duval Diagnosis Zone", "Duval Diagnosis Type", "Pentagon Zone",
        "Duval Zone",
        "Duval Fault Type",
        "CH4 Duval (%)",
        "C2H2 Duval (%)",
        "C2H4 Duval (%)",
        "Pentagon Dominant Gas",
        "Pentagon Pattern",
        "Pentagon Centroid X",
        "Pentagon Centroid Y",
        "H2 Pentagon (%)",
        "CH4 Pentagon (%)",
        "C2H6 Pentagon (%)",
        "C2H4 Pentagon (%)",
        "C2H2 Pentagon (%)",
        "Dominant Factor",
        "Abnormal Parameter",
        "Reference Limit",
        "Abnormal Detail",
        "Severity",
        "Action Required",
        "Smart Explanation",
        "Recommendation",
        "Assessment Type",
        "Confidence Level",
    ]
    for col in required_cols:
        df = safe_column(df, col, "")
    df["Analysis Mode"] = df["Analysis Mode"].replace("", "Legacy (mode belum disimpan)")
    df["HI (%)"] = pd.to_numeric(df["HI (%)"], errors="coerce")
    df["BDV"] = pd.to_numeric(df["BDV"], errors="coerce")
    df["Water Content"] = pd.to_numeric(df["Water Content"], errors="coerce")
    df["Time"] = pd.to_datetime(df["Time"], errors="coerce")
    return df
def make_historical_summary_df(history_df):
    df = prepare_history_for_report(history_df)
    valid_df = df[
        df["Transformer No"].notna()
        & (df["Transformer No"].astype(str).str.strip() != "")
        & (df["Transformer No"].astype(str).str.strip() != "-")
        & (df["Transformer No"].astype(str).str.lower() != "nan")
    ].copy()
    if valid_df.empty:
        return pd.DataFrame(
            columns=[
                "Transformer No", "Analysis Mode",
                "Test Count",
                "First Test",
                "Latest Test",
                "First HI (%)",
                "Latest HI (%)",
                "HI Change (%)",
                "Trend Status",
                "Latest Condition",
                "Latest Dominant Factor",
                "Latest Severity",
                "Latest Recommendation",
            ]
        )
    summary_rows = []
    for (trafo_no, mode), group in valid_df.groupby(["Transformer No", "Analysis Mode"]):
        group = group.sort_values("Time")
        first_row = group.iloc[0]
        latest_row = group.iloc[-1]
        first_hi = first_row["HI (%)"]
        latest_hi = latest_row["HI (%)"]
        if pd.isna(first_hi) or pd.isna(latest_hi):
            delta_hi = None
            trend_status = "Insufficient Data"
        else:
            delta_hi = latest_hi - first_hi
            if delta_hi <= -5:
                trend_status = "Declining"
            elif delta_hi >= 5:
                trend_status = "Improving"
            else:
                trend_status = "Stable"
        summary_rows.append(
            {
                "Transformer No": trafo_no,
                "Analysis Mode": mode,
                "Test Count": len(group),
                "First Test": first_row["Time"],
                "Latest Test": latest_row["Time"],
                "First HI (%)": round(first_hi, 2) if pd.notna(first_hi) else "",
                "Latest HI (%)": round(latest_hi, 2) if pd.notna(latest_hi) else "",
                "HI Change (%)": round(delta_hi, 2) if delta_hi is not None else "",
                "Trend Status": trend_status,
                "Latest Condition": latest_row["Overall Condition"],
                "Latest Dominant Factor": latest_row["Dominant Factor"],
                "Latest Severity": latest_row["Severity"],
                "Latest Recommendation": latest_row["Recommendation"],
            }
        )
    return pd.DataFrame(summary_rows)
def make_multi_test_detail_df(history_df):
    df = prepare_history_for_report(history_df)
    valid_df = df[
        df["Transformer No"].notna()
        & (df["Transformer No"].astype(str).str.strip() != "")
        & (df["Transformer No"].astype(str).str.strip() != "-")
        & (df["Transformer No"].astype(str).str.lower() != "nan")
    ].copy()
    if valid_df.empty:
        return pd.DataFrame()
    count_df = valid_df.groupby(["Transformer No", "Analysis Mode"]).size().reset_index(name="Test Count")
    multi_ids = set(zip(count_df[count_df["Test Count"] > 1]["Transformer No"].astype(str),
                        count_df[count_df["Test Count"] > 1]["Analysis Mode"].astype(str)))
    multi_df = valid_df[
        valid_df.apply(lambda row: (str(row["Transformer No"]), str(row["Analysis Mode"])) in multi_ids, axis=1)
    ].copy()
    multi_df = multi_df.sort_values(["Transformer No", "Analysis Mode", "Time"])
    detail_cols = [
        "Time", "Analysis Mode",
        "Transformer No",
        "Capacity",
        "Voltage Class",
        "BDV",
        "Water Content",
        "HI (%)",
        "Overall Condition",
        "Calculated Condition",
        "DGA Indication",
        "IEEE TDCG Condition", "DGA Status 2019", "DGA Screening Note",
        "Duval Method", "Duval Diagnosis Zone", "Duval Diagnosis Type", "Pentagon Zone",
        "Duval Zone",
        "Duval Fault Type",
        "CH4 Duval (%)",
        "C2H2 Duval (%)",
        "C2H4 Duval (%)",
        "Pentagon Dominant Gas",
        "Pentagon Pattern",
        "Pentagon Centroid X",
        "Pentagon Centroid Y",
        "H2 Pentagon (%)",
        "CH4 Pentagon (%)",
        "C2H6 Pentagon (%)",
        "C2H4 Pentagon (%)",
        "C2H2 Pentagon (%)",
        "Dominant Factor",
        "Abnormal Parameter",
        "Severity",
        "Action Required",
        "Smart Explanation",
        "Recommendation",
    ]
    return multi_df[detail_cols].copy()
def make_latest_assessment_df(history_df):
    df = prepare_history_for_report(history_df)
    valid_df = df[
        df["Transformer No"].notna()
        & (df["Transformer No"].astype(str).str.strip() != "")
        & (df["Transformer No"].astype(str).str.strip() != "-")
        & (df["Transformer No"].astype(str).str.lower() != "nan")
    ].copy()
    if valid_df.empty:
        return df.head(0)
    latest_rows = []
    # Same transformer can have separate Capstone and Skripsi assessments.
    for _, group in valid_df.groupby(["Transformer No", "Analysis Mode"]):
        group = group.sort_values("Time")
        latest_rows.append(group.iloc[-1])
    latest_df = pd.DataFrame(latest_rows)
