GENERAL_REQUIRED_FIELDS = ("BDV", "Water Content")
GENERAL_GAS_FIELDS = ("H2", "CH4", "C2H6", "C2H4", "C2H2", "CO", "CO2")
GENERAL_OPTIONAL_HI_FIELDS = ("IFT", "Acidity", "Color", "Furan", "Power Factor", "Loss HIF")


def general_column_guess(columns):
    """Match only exact normalized aliases or exact alias plus a known unit suffix."""
    mapped = {}
    items = [(col, normalize_col_name(col)) for col in columns if str(col) != "_insight_excel_row"]
    used = set()
    for field, aliases in GENERAL_IMPORT_FIELDS.items():
        choices = {normalize_col_name(a) for a in aliases}
        chosen = None
        for column, norm in items:
            if column not in used and norm in choices:
                chosen = column
                break
        if chosen is None:
            for column, norm in items:
                if column in used: continue
                if any(norm == name+unit for name in choices for unit in ("ppm", "kv", "mnm", "dynecm", "mgkohg", "percent")):
                    chosen = column
                    break
        if chosen is not None:
            mapped[field] = chosen
            used.add(chosen)
    return mapped


def general_read_upload(upload, sheet_name=None):
    """Read CSV/XLSX with a possible preamble, while retaining real source row numbers."""
    data = upload.getvalue()
    if not data:
        raise ValueError("File kosong.")
    if len(data) > 18 * 1024 * 1024:
        raise ValueError("File terlalu besar (maksimum 18 MB). Bagi menjadi beberapa file.")
    filename = str(getattr(upload, "name", "")).lower()
    if filename.endswith(".csv"):
        import csv
        import io
        try:
            decoded = data.decode("utf-8-sig")
        except UnicodeDecodeError:
            decoded = data.decode("cp1252")
        sample_lines = [line for line in decoded.splitlines()[:40] if line.strip()]
        if not sample_lines:
            raise ValueError("File CSV tidak berisi data.")
        # Inspect multiple lines so a descriptive title above the actual CSV header
        # cannot cause a false delimiter or pandas' varying-column-width error.
        candidates = [";", ",", "\t", "|"]
        separator = max(candidates, key=lambda c: sum(line.count(c) for line in sample_lines))
        if sum(line.count(separator) for line in sample_lines) == 0:
            raise ValueError("CSV membutuhkan pemisah kolom seperti koma atau titik koma.")
        raw_rows = list(csv.reader(io.StringIO(decoded), delimiter=separator))
        raw = pd.DataFrame(raw_rows).replace("", pd.NA).dropna(how="all")
    elif filename.endswith(".xlsx"):
        raw = pd.read_excel(BytesIO(data), sheet_name=sheet_name if sheet_name is not None else 0,
                            header=None, engine="openpyxl", dtype=object)
    else:
        raise ValueError("Gunakan file Excel .xlsx atau .csv.")
    if raw.empty:
        raise ValueError("Lembar data kosong.")
    # Locate the most likely row of headers, even if the first lines contain titles.
    best_index, best_score = 0, -1
    for idx, row in raw.head(35).iterrows():
        columns = [str(v).strip() for v in row.tolist() if is_available(v)]
        guesses = general_column_guess(columns)
        score = len(guesses) + sum(3 for key in GENERAL_REQUIRED_FIELDS if key in guesses)
        if score > best_score:
            best_score, best_index = score, idx
    if best_score < 2:
        best_index = 0
    names = make_unique_columns(raw.loc[best_index].tolist())
    result = raw.loc[best_index+1:].copy()
    result.columns = names
    result = result[[c for c in names if not str(c).startswith("DropColumn_")]]
    result = result.dropna(how="all").copy()
    result["_insight_excel_row"] = result.index.astype(int) + 1
    result.reset_index(drop=True, inplace=True)
    return result, int(best_index)+1


def general_apply_mapping(original, mapping):
    """Create canonical columns used by the existing validated calculator."""
    chosen = [source for source in mapping.values() if source is not None]
    if len(chosen) != len(set(chosen)):
        raise ValueError("Satu kolom Excel tidak boleh digunakan untuk dua parameter. Periksa pemetaan kolom.")
    transformed = original.copy()
    # Copy from ORIGINAL, not from partially transformed data, to avoid collisions.
    for target, source in mapping.items():
        if source is not None:
            transformed[target] = original[source]
        elif target in transformed.columns:
            transformed.drop(columns=[target], inplace=True)
    return transformed


def general_row_assessment(row):
    """Preview readiness only; no scores, assumed gases or false normal labels."""
    bdv, wc = row.get("BDV", ""), row.get("Water Content", "")
    excel_row = int(row.get("_insight_excel_row", 0))
    identifier = row.get("Transformer No", "")
    identifier = str(identifier).strip() if is_available(identifier) else f"Baris {excel_row}"
    hi_ok = is_numeric_available(bdv) and is_numeric_available(wc) and to_number(bdv)>0 and to_number(wc)>=0
    names = GENERAL_GAS_FIELDS + GENERAL_OPTIONAL_HI_FIELDS
    issues = [name for name in names if is_available(row.get(name, "")) and
              (not is_numeric_available(row[name]) or to_number(row[name])<0)]
    if is_available(row.get("Voltage Class", "")):
        try:
            normalize_voltage_class(row["Voltage Class"])
        except ValueError:
            issues.append("Kelas tegangan tidak dikenali")
    if is_available(row.get("Loss HIF", "")) and is_numeric_available(row.get("Loss HIF")):
        if to_number(row["Loss HIF"]) not in (0,1,2,3,4):
            issues.append("Loss HIF (harus 0–4)")
    gas = {name: row.get(name, "") for name in GENERAL_GAS_FIELDS}
    valid = lambda keys: all(is_numeric_available(gas[k]) and to_number(gas[k])>=0 for k in keys)
    dp_keys=("H2","CH4","C2H6","C2H4","C2H2")
    dt_keys=("CH4","C2H4","C2H2")
    dp = valid(dp_keys) and sum(to_number(gas[k]) for k in dp_keys)>0
    dt = valid(dt_keys) and sum(to_number(gas[k]) for k in dt_keys)>0
    dga = valid(GENERAL_GAS_FIELDS)
    coverage = 2 + int(dga) + sum(int(is_numeric_available(row.get(k, ""))) for k in GENERAL_OPTIONAL_HI_FIELDS)
    reason = ("Siap" if hi_ok and not issues else
              "BDV/WC belum valid" if not hi_ok else
              "Nilai tidak valid: " + ", ".join(issues))
    return {"Pilih":bool(hi_ok and not issues), "Baris":excel_row, "Transformator":identifier,
            "HI":f"{coverage}/9" if hi_ok else "—",
            "DGA Status":"Tersedia" if dga else "Belum lengkap",
            "Duval":"DP1" if dp else "DT1" if dt else "Belum tersedia",
            "Keterangan": reason}


def general_input_from_row(row, username=""):
    """Map standardized import row into the EXISTING scientific engine."""
    def val(field, default=""):
        v = row.get(field, default)
        return v if is_available(v) else default
    test_date=val("Date", app_now().strftime("%Y-%m-%d"))
    try: test_date=pd.to_datetime(test_date).strftime("%Y-%m-%d %H:%M:%S")
    except (ValueError,TypeError): test_date=app_now_text()
    gas={name:val(name) for name in GENERAL_GAS_FIELDS}
    dga_ready=valid_gas_values(list(gas.values()))
    optional={name:val(name) for name in GENERAL_OPTIONAL_HI_FIELDS}
    data={"Username":username, "Analysis Mode":"Capstone", "Time":test_date,
          "Transformer No":val("Transformer No", f"Baris {row.get('_insight_excel_row','-')}"),
          "Capacity":val("Capacity", "-"), "Voltage Class":val("Voltage Class", "≤ 69 kV"),
          "BDV":val("BDV"), "Water Content":val("Water Content"),
          "Source Label":val("Source Label"), "O2/N2 Ratio":val("O2/N2 Ratio"),
          "Use DGA":dga_ready, **gas,
          "Use IFT":is_available(optional["IFT"]), "IFT":optional["IFT"],
          "Use Acidity":is_available(optional["Acidity"]), "Acidity":optional["Acidity"],
          "Use Color":is_available(optional["Color"]), "Color":optional["Color"],
          "Use Furan":is_available(optional["Furan"]), "Furan":optional["Furan"],
          "Use PF":is_available(optional["Power Factor"]), "Power Factor":optional["Power Factor"],
          "Use Loss":is_available(optional["Loss HIF"]), "Loss HIF":optional["Loss HIF"] if is_available(optional["Loss HIF"]) else 4,
          "Analysis Modules":["hi"] + (["dga"] if dga_ready else [])}
    dp_fields=("H2","CH4","C2H6","C2H4","C2H2")
    if valid_gas_values([gas[k] for k in dp_fields]) and sum(to_number(gas[k]) for k in dp_fields)>0:
        data["Analysis Modules"].append("dp1")
    elif valid_gas_values([gas[k] for k in ("CH4","C2H4","C2H2")]) and sum(to_number(gas[k]) for k in ("CH4","C2H4","C2H2"))>0:
        data["Analysis Modules"].append("dt1")
    return data

def make_template_excel():
    output = BytesIO()
    template_columns = [
        "Date",
        "Transformer No",
        "Capacity",
        "Voltage Class",
        "BDV",
        "Water Content",
        "H2",
        "CH4",
        "CO",
        "CO2",
        "C2H4",
        "C2H6",
        "C2H2",
        "IFT",
        "Acidity",
        "Color",
        "Furan",
        "Power Factor",
        "Loss HIF",
        "O2/N2 Ratio",
        "Source Label",
    ]
    example_rows = pd.DataFrame(
        [
            {
                "Date": "2026-07-28",
                "Transformer No": "00367",
                "Capacity": "1000 kVA",
                "Voltage Class": "≤ 69 kV",
                "BDV": 45,
                "Water Content": 20,
                "H2": 50,
                "CH4": 30,
                "CO": 200,
                "CO2": 1500,
                "C2H4": 20,
                "C2H6": 15,
                "C2H2": 0,
                "IFT": 30,
                "Acidity": 0.03,
                "Color": 1.0,
                "Furan": 0.05,
                "Power Factor": 0.3,
                "Loss HIF": 4,
                "O2/N2 Ratio": "",
                "Source Label": "Good",
            }
        ],
        columns=template_columns,
    )
    instructions_df = pd.DataFrame(
        {
            "Column Name": template_columns,
            "Required?": [
                ("Required" if key in ("BDV","Water Content")
                 else "Opsional; 7 gas lengkap untuk DGAF dan status DGA" if key in IEEE2019_GAS_NAMES
                 else "Opsional (identitas atau data tambahan)")
                for key in template_columns
            ],
            "Description": [
                "Sampling/analysis date, format YYYY-MM-DD",
                "Transformer ID/serial number, used to track history",
                "Example: 1000 kVA",
                "Choose one: ≤ 69 kV / 69 kV - 230 kV / ≥ 230 kV",
                "Breakdown voltage / dielectric strength (kV)",
                "Water content in oil (ppm)",
                "Hydrogen (ppm); DP1 memerlukan lima gas, sedangkan DGA Status dan DGAF memerlukan tujuh gas",
                "Methane (ppm)",
                "Carbon monoxide (ppm)",
                "Carbon dioxide (ppm)",
                "Ethylene (ppm)",
                "Ethane (ppm)",
                "Acetylene (ppm)",
                "Interfacial tension (dyne/cm)",
                "Acid number",
                "Oil color index",
                "Furan / 2-FAL (ppm)",
                "Power factor (%)",
                "Manual score 0-4 if load/loss history is assessed manually",
                "Optional measured O2/N2 ratio for selecting the IEEE 2019 norm table",
                "Existing HI label if available, for comparison: Very Good/Good/Fair/Poor/Very Poor",
            ],
        }
    )
    with pd.ExcelWriter(output, engine="openpyxl") as writer:
        example_rows.to_excel(writer, index=False, sheet_name="Data Input")
        instructions_df.to_excel(writer, index=False, sheet_name="Instructions")
        workbook = writer.book
        from openpyxl.styles import Alignment, Font, PatternFill
        header_fill = PatternFill("solid", fgColor="D9EAF7")
        header_font = Font(bold=True)
        for sheet_name in workbook.sheetnames:
            worksheet = workbook[sheet_name]
            for cell in worksheet[1]:
                cell.font = header_font
                cell.fill = header_fill
                cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
            for column_cells in worksheet.columns:
                max_length = 0
                column_letter = column_cells[0].column_letter
                for cell in column_cells:
                    try:
                        value_length = len(str(cell.value))
                        if value_length > max_length:
                            max_length = value_length
                    except Exception:
                        pass
                worksheet.column_dimensions[column_letter].width = min(max_length + 4, 40)
    output.seek(0)
    return output
def detect_batch_module_availability(batch_df):
    """A module is available when at least one processable row has the data it needs."""
    col_map = {normalize_col_name(col): col for col in batch_df.columns}
    availability = {"hi": False, "dga": False, "dt1": False, "dp1": False}
    for _, row in batch_df.iterrows():
        bdv_value = get_col_value(row, col_map, ["BDV", "Breakdown Voltage", "Dielectric Strength"], "")
        wc_value = get_col_value(row, col_map, ["Water Content", "Water Conten", "WC", "Moisture"], "")
        if not (is_available(bdv_value) and is_available(wc_value)):
            continue
        availability["hi"] = True
        row_av = module_availability(
            get_col_value(row, col_map, ["H2", "H₂"], ""),
            get_col_value(row, col_map, ["CH4", "CH₄"], ""),
            get_col_value(row, col_map, ["CO"], ""),
            get_col_value(row, col_map, ["CO2", "CO₂"], ""),
            get_col_value(row, col_map, ["C2H4", "C₂H₄"], ""),
            get_col_value(row, col_map, ["C2H6", "C₂H₆"], ""),
            get_col_value(row, col_map, ["C2H2", "C₂H₂"], ""),
        )
        for key in ["dga", "dt1", "dp1"]:
            availability[key] = availability[key] or row_av[key]
    return availability


_SEV_COLOR = {"Normal": "#18A775", "Low": "#18A775", "Medium": "#F1A21A", "High": "#EE7A2B", "Critical": "#E45463"}
_COND_COLOR = {"Very Good": "#18A775", "Good": "#18A775", "Fair": "#F1A21A", "Poor": "#EE7A2B", "Very Poor": "#E45463"}
_STATUS_CHIP = {"Good": "#18A775", "Caution": "#F1A21A", "Need attention": "#EE7A2B", "Poor": "#E45463", "Very poor": "#B3202F"}
_GAS_PARAMS = ["H2", "CH4", "CO", "CO2", "C2H4", "C2H6", "C2H2"]
_UNITS = {"H2": "ppm", "CH4": "ppm", "CO": "ppm", "CO2": "ppm", "C2H4": "ppm", "C2H6": "ppm", "C2H2": "ppm",
          "BDV": "kV", "Water Content": "ppm", "IFT": "mN/m", "Acidity": "mg KOH/g", "Color": "", "Furan": "ppm",
          "Power Factor": "%", "Loss HIF": ""}
_ASPECT_NAMES = {"DGA HIF": "Dissolved gas (DGA)", "Oil Quality HIF": "Oil quality", "Furan HIF": "Paper insulation (furan)",
                 "Power Factor HIF": "Dielectric (power factor)", "Load/Loss HIF": "Load / loss"}


def _chip(text, color):
    return (f'<span style="font-size:10px;font-weight:800;color:#fff;background:{color};padding:3px 10px;'
            f'border-radius:999px;white-space:nowrap">{escape(str(text))}</span>')


def _step_header(n, title, sub):
    return (f'<div id="step-{n}"></div><div style="display:flex;align-items:center;gap:12px;margin:28px 0 12px">'
            f'<div style="min-width:34px;height:34px;border-radius:50%;background:#2F78F6;color:#fff;display:flex;'
            f'align-items:center;justify-content:center;font-weight:800">{n}</div>'
            f'<div><div style="font-size:19px;font-weight:800;color:var(--text);line-height:1.2">{title}</div>'
            f'<div style="font-size:12px;color:var(--muted)">{sub}</div></div></div>')


def _mini_card(title, value_html, sub="", color="#7E92A6"):
    return (f'<div style="padding:12px 14px;border:1px solid var(--border);border-left:4px solid {color};'
            f'border-radius:12px;background:var(--card)">'
            f'<div style="font-size:10px;text-transform:uppercase;letter-spacing:1px;font-weight:800;color:var(--muted)">{title}</div>'
            f'<div style="font-size:16px;font-weight:800;color:var(--text);margin-top:4px;line-height:1.25">{value_html}</div>'
            f'<div style="font-size:11px;color:var(--muted);margin-top:4px;line-height:1.4">{sub}</div></div>')


def _param_status(param, score):
    try:
        sc = int(float(score))
    except Exception:
        return None
    if param in _GAS_PARAMS:
        return {1: "Good", 2: "Good", 3: "Caution", 4: "Need attention", 5: "Poor", 6: "Very poor"}.get(sc, "Very poor" if sc > 6 else "Good")
    return {1: "Good", 2: "Caution", 3: "Poor", 4: "Very poor"}.get(sc, "Very poor" if sc > 4 else "Good")


def _fmt_value(v):
    try:
        if str(v).strip() in ("", "None", "nan"):
            return None
        return f"{float(v):g}"
    except Exception:
        return str(v) if str(v).strip() else None


def _html_table(headers, rows):
    head = "".join(f'<th style="padding:9px 10px">{h}</th>' for h in headers)
    body = "".join(
        '<tr style="border-top:1px solid var(--border)">' + "".join(f'<td style="padding:7px 10px;color:var(--text)">{c}</td>' for c in r) + "</tr>"
        for r in rows
    )
    return ('<div style="border:1px solid var(--border);border-radius:13px;background:var(--card);overflow-x:auto">'
            '<table style="width:100%;border-collapse:collapse;font-size:12px"><thead>'
            f'<tr style="text-align:left;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.9px">{head}</tr></thead>'
            f'<tbody>{body}</tbody></table></div>')


def render_assessment_results(result, record, modules):
    """Capstone: easy-to-read result first; technical material stays optional."""
    methods = [m for m in modules if m in MODULE_LABELS] or ["hi"]
    tid = str(record.get("Transformer No", "-"))
    ringkas = ringkasan_capstone_3_baris(record)
    hi = record.get("HI (%)")
    method = str(record.get("Duval Method", "Not Available")).upper()
    zone = str(record.get("Duval Diagnosis Zone", "-"))
    dga = record.get("DGA Status 2019")

    st.markdown(f"### Hasil analisis - Trafo {escape(tid)}")
    a,b,c = st.columns(3)
    try:
        a.metric("Health Index (" + str(record.get("Calculated Condition", "-")) + ")", f"{float(hi):.1f}%")
    except (ValueError, TypeError):
        a.metric("Health Index (" + str(record.get("Calculated Condition", "-")) + ")", "-")
    b.metric("DGA Status (skrining)", str(dga) if str(dga) in ("1", "2", "3") else "-")
    c.metric("Diagnosis Duval", f"{method} {zone}" if method in ("DT1", "DP1") else "Tidak tersedia")
    st.markdown(capstone_ringkasan_tabel_html(ringkas), unsafe_allow_html=True)
    if ringkas["parsial"]:
        st.warning("HI menggunakan data parsial. Lengkapi 9 parameter sebelum menyimpulkan kondisi kesehatan penuh.")
    st.caption("Overall Condition merangkum hasil metode, bukan menciptakan skor/kategori gabungan baru. DGA Status merupakan skrining satu sampel.")

    if ringkas["duval_ada"]:
        with st.expander(f"Lihat gambar diagnosis {method} - zona {zone}", expanded=False):
            if method == "DP1" and result.get("pentagon", {}).get("available"):
                st.plotly_chart(make_duval_pentagon_plot(result["pentagon"], tid), use_container_width=True, theme=None)
            elif method == "DT1" and result.get("duval", {}).get("available"):
                st.plotly_chart(make_duval_triangle_plot(result["duval"], tid), use_container_width=True, theme=None)
            else:
                st.info("Diagram belum tersedia untuk assessment ini.")
            st.caption("Titik penanda adalah hasil konsentrasi gas trafo, bukan bukti definitif gangguan.")

    with st.expander("Lihat detail angka, skor dan parameter (untuk verifikasi)", expanded=False):
        cols = ["BDV", "Water Content", "IFT", "Acidity", "Color", "Furan", "Power Factor", "Loss HIF", "H2", "CH4", "C2H6", "C2H4", "C2H2", "CO", "CO2"]
        st.dataframe(pd.DataFrame([{"Parameter":k, "Nilai":record.get(k, "-")} for k in cols]),
                     use_container_width=True, hide_index=True)
        if result.get("detail_df") is not None:
            st.dataframe(result["detail_df"], use_container_width=True, hide_index=True)
        st.write("OilQF:", record.get("OilQF", "-"), "| DGAF:", record.get("DGAF", "-"))
        st.write("Kelengkapan:", record.get("HI Input Coverage", "-"))
        st.code(str(record.get("HI Formula", "-")))
        if result.get("abnormal_df") is not None and not result["abnormal_df"].empty:
            st.markdown("**Parameter yang perlu ditinjau**")
            st.dataframe(result["abnormal_df"], use_container_width=True, hide_index=True)
        st.caption(str(record.get("DGA Screening Note", "")))
        st.caption(str(record.get("Recommendation", "")))
    with st.expander("Lihat visualisasi komponen trafo (opsional)", expanded=False):
        render_interactive_transformer_3d_plotly(record, show_dga=False)


def render_duval_batch_visualization(result_df, show_triangle=True, show_pentagon=True):
    """Plot only one diagnosed method per V5 assessment; don't relabel old data."""
    if result_df is None or result_df.empty:
        return
    st.markdown("### Duval Diagnosis — Selected Method")
    df=result_df.copy()
    if "Transformer No" not in df.columns:
        st.info("No transformer identifiers available.")
        return
    keys=df["Transformer No"].astype(str).str.strip()
    df=df.loc[~keys.str.lower().isin({"","-","nan","none","null"})].reset_index(drop=True)
    if df.empty:
        st.info("No valid transformer identifiers available.")
        return
    ix=st.selectbox("Select transformer for Duval visualization", list(range(len(df))),
                    format_func=lambda i:f"{df.iloc[i].get('Transformer No','-')} | {df.iloc[i].get('Duval Method','Legacy')}",
                    key="batch_duval_visual_select")
    row=df.iloc[ix].to_dict()
    meth=str(row.get("Duval Method","")).strip().upper()
    if meth not in ("DT1","DP1"):
        st.info("Legacy or missing Duval selection. Stored results preserved, no V5 reclassification.")
        return
    tri,pent=selected_duval_results_from_record(row)
    if meth=="DT1" and show_triangle and tri.get("available"):
        st.plotly_chart(make_duval_triangle_plot(tri,row.get("Transformer No","-")),use_container_width=True,theme=None)
        st.caption("DT1 zone: " + str(tri.get("zone","Not Available")))
    elif meth=="DP1" and show_pentagon and pent.get("available"):
        st.plotly_chart(make_duval_pentagon_plot(pent,row.get("Transformer No","-")),use_container_width=True,theme=None)
        st.caption("DP1 zone: " + str(pent.get("zone","Not Available")))
    else:
        st.info("The selected Duval method is not available in these visual settings.")

