import base64 as _insight_base64

_INSIGHT_LANDING_CSS = '/* INSIGHT / Editorial-Industrial landing: bright canvas, cobalt machinery panel,\n   genuine user-provided transformer photograph, accessible CTA, responsive grid. */\n.ins4-shell,.ins4-shell *,.ins4-shell *::before,.ins4-shell *::after{box-sizing:border-box}\n.ins4-shell{--ink:#0b1d34;--cobalt:#154db8;--electric:#276eff;--orange:#ef663b;--cream:#f7f8f4;--muted:#58697c;color:var(--ink);background:transparent;width:100%;max-width:1500px;margin:0 auto;font-family:Inter,Arial,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}\n.ins4-shell a{text-decoration:none!important}\n.ins4-header{height:82px;padding:0 6px 0 2px;display:flex;align-items:center;justify-content:space-between;gap:22px}\n.ins4-brand{display:flex;align-items:center;gap:12px;color:var(--ink)!important}\n.ins4-brandmark{width:43px;height:43px;background:var(--ink);color:#c1f7e6;display:grid;place-items:center;border-radius:11px}\n.ins4-brandwords b{display:block;letter-spacing:.18em;font-size:20px;color:#0a203a!important;line-height:1.05}\n.ins4-brandwords small{display:block;font-size:9px;font-weight:750;letter-spacing:.095em;color:#7f909f!important;margin-top:5px}\n.ins4-nav{display:flex;align-items:center;gap:30px}\n.ins4-nav>a:not(.ins4-nav-cta){color:#50657e!important;font-size:12px;font-weight:750}\n.ins4-nav>a:not(.ins4-nav-cta):hover{color:var(--cobalt)!important}\n.ins4-nav-cta{border-radius:7px;background:var(--ink)!important;color:#fff!important;padding:13px 18px;font-size:12px;font-weight:800;display:inline-flex;align-items:center;gap:18px;min-height:45px;box-shadow:0 10px 24px rgba(9,30,56,.14)}\n.ins4-nav-cta span{font-size:18px;color:#83efd7}\n.ins4-nav-cta:hover{background:#184782!important}\n.ins4-hero{display:grid;grid-template-columns:53% 47%;min-height:660px;overflow:hidden;border-radius:22px;background:#fbfaf6;box-shadow:0 15px 48px rgba(26,58,91,.08);border:1px solid #e8e9e4}\n.ins4-hero-left{position:relative;display:flex;flex-direction:column;min-width:0;padding:29px 64px 27px 66px;background:#fbfaf6}\n.ins4-topline{display:flex;gap:12px;align-items:center;color:#556b7e;font-size:10px;font-weight:850;letter-spacing:.11em}\n.ins4-dash{width:26px;height:4px;background:#f06b42;display:inline-block}\n.ins4-topline-num{margin-left:auto;color:#9eabb6;white-space:nowrap}\n.ins4-hero-main{margin:auto 0;max-width:650px;padding:48px 0 46px}\n.ins4-edition{font-size:10px;font-weight:850;letter-spacing:.2em;color:#1762ba;margin-bottom:22px}\n.ins4-hero h1{font-size:clamp(59px,6.25vw,100px);letter-spacing:-.077em;line-height:.96;font-weight:880;color:#0c243e!important;margin:0 0 32px;max-width:680px}\n.ins4-hero h1 span{font-family:Georgia,Times,serif;font-style:italic;font-weight:600;letter-spacing:-.09em;color:#245ed4!important}\n.ins4-lead{font-size:15.5px;line-height:1.85;color:#536a7e!important;max-width:475px;margin:0 0 31px}\n.ins4-action-row{display:flex;align-items:center;gap:23px;flex-wrap:wrap}\n.ins4-start{display:inline-flex;align-items:center;justify-content:space-between;gap:28px;background:#ef663b!important;color:#fff!important;font-size:14px;font-weight:850;min-height:57px;padding:0 15px 0 24px;border-radius:9px;box-shadow:0 11px 25px rgba(239,102,59,.23);transition:transform .15s,box-shadow .15s}\n.ins4-start span{background:rgba(255,255,255,.21);border-radius:6px;width:32px;height:32px;display:grid;place-items:center;font-size:19px;color:#fff}\n.ins4-start:hover{transform:translateY(-2px);box-shadow:0 17px 28px rgba(239,102,59,.3)}\n.ins4-discover{font-size:13px;font-weight:800;color:#183957!important;display:inline-flex;gap:13px;align-items:center;border-bottom:1px solid #9aa8b6;padding:13px 0 8px}\n.ins4-discover span{font-size:19px;color:#e9683d}\n.ins4-hero-bottom{display:flex;align-items:center;gap:11px;border-top:1px solid #dce2e3;padding-top:24px;color:#496072;font-size:10px;font-weight:830;letter-spacing:.115em}\n.ins4-tick{height:8px;width:8px;background:#245ed4;display:inline-block;transform:rotate(45deg)}\n.ins4-hero-bottom-arrow{margin-left:auto;font-size:21px;color:#1859b3}\n.ins4-hero-right{background:linear-gradient(147deg,#0a337f 0%,#1652b5 58%,#2774dc 100%);position:relative;isolation:isolate;display:flex;flex-direction:column;min-width:0;color:#fff;padding:29px 30px 27px}\n.ins4-right-grid{position:absolute;inset:0;pointer-events:none;opacity:.23;background-image:linear-gradient(rgba(255,255,255,.15) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.15) 1px,transparent 1px);background-size:44px 44px;mask-image:linear-gradient(145deg,transparent 10%,black 100%);z-index:-1}\n.ins4-right-top{display:flex;align-items:center;justify-content:space-between;gap:12px;color:#e2edff;font-size:10px;font-weight:850;letter-spacing:.11em;min-width:0}\n.ins4-real-photo{font-size:9px;white-space:nowrap;border:1px solid rgba(255,255,255,.32);border-radius:50px;padding:7px 10px}\n.ins4-real-photo span{display:inline-block;width:6px;height:6px;background:#8effd1;border-radius:50%;margin-right:6px}\n.ins4-visual{flex:1;min-height:430px;position:relative;display:flex;align-items:center;justify-content:center;isolation:isolate}\n.ins4-orbit{pointer-events:none;position:absolute;border:1px solid rgba(210,235,255,.24);border-radius:50%;width:min(90%,530px);aspect-ratio:1;left:50%;top:50%;transform:translate(-50%,-50%)}\n.ins4-orbit-inner{width:min(65%,385px);border-color:rgba(210,235,255,.16)}\n.ins4-visual-no{position:absolute;top:16%;left:4%;font-size:180px;line-height:1;font-weight:900;letter-spacing:-.1em;color:rgba(255,255,255,.075);user-select:none}\n.ins4-transformer{position:relative;z-index:3;display:block;width:min(100%,520px);height:auto;max-height:490px;object-fit:contain;filter:drop-shadow(5px 30px 26px rgba(0,20,63,.34));transition:transform .3s;}\n.ins4-transformer:hover{transform:translateY(-4px)}\n.ins4-corner-mark{position:absolute;width:32px;height:32px;z-index:4;border-color:#a1f3dc;border-style:solid}\n.ins4-corner-a{top:9%;left:7%;border-width:2px 0 0 2px}.ins4-corner-b{right:6%;bottom:12%;border-width:0 2px 2px 0}\n.ins4-image-caption{position:absolute;z-index:5;left:0;bottom:2%;border-left:3px solid #82f6d8;padding:6px 13px;background:rgba(9,38,94,.36);backdrop-filter:blur(5px)}\n.ins4-image-caption span{font-size:9px;display:block;font-weight:720;letter-spacing:.12em;color:#d1e6fa;text-transform:uppercase}\n.ins4-image-caption strong{font-size:14px;color:#fff;display:block;margin-top:4px}\n.ins4-right-bottom{border-top:1px solid rgba(255,255,255,.28);padding-top:24px;display:flex;justify-content:space-between;gap:14px;align-items:center}\n.ins4-right-data-label{font-size:10px;font-weight:850;letter-spacing:.16em;color:#d2e6ff}\n.ins4-data-list{display:flex;gap:9px;flex-wrap:wrap}\n.ins4-data-list span{border:1px solid rgba(255,255,255,.3);padding:8px 10px;border-radius:4px;font-size:10px;font-weight:850;color:#fff}\n.ins4-ticker{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));background:#0b203b;border-radius:0 0 15px 15px;margin:0 14px;padding:20px 15px;gap:14px;color:#e6f2ff;transform:translateY(-1px)}\n.ins4-ticker>div{display:flex;gap:12px;align-items:center;justify-content:center;font-size:11px;font-weight:850;letter-spacing:.12em}\n.ins4-ticker-star{color:#75f1d0;font-size:21px}\n.ins4-capabilities{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:80px;padding:110px 20px 95px 20px;align-items:start}\n.ins4-section-kicker{font-size:11px;letter-spacing:.13em;font-weight:850;color:#5d7183;margin-bottom:32px}\n.ins4-section-kicker span{font-size:12px;padding:9px 11px;background:#ffede6;color:#e7633a;border-radius:4px;margin-right:10px}\n.ins4-section-intro h2{font-size:clamp(39px,4.3vw,64px);letter-spacing:-.062em;line-height:1.07;color:#09213d!important;margin:0 0 25px;font-weight:880}\n.ins4-section-intro h2 em{font-family:Georgia,Times,serif;font-weight:500;color:#235bc1;font-size:.85em;white-space:nowrap}\n.ins4-section-intro p{font-size:14px;line-height:1.85;color:#6b7f91;max-width:415px}\n.ins4-rows{border-top:1px solid #cdd8e1}\n.ins4-cap-row{display:grid;grid-template-columns:27px 57px minmax(0,1fr) 22px;gap:20px;align-items:center;padding:27px 0;border-bottom:1px solid #cdd8e1}\n.ins4-row-index{font-size:10px;color:#8da2b5;font-weight:850;align-self:start;padding-top:12px}\n.ins4-row-icon{width:57px;height:57px;border-radius:14px;background:#dceafd;color:#1b58b4;display:grid;place-items:center;font-size:30px;font-weight:780}\n.ins4-icon-b{background:#dff5ed;color:#119b80}.ins4-icon-c{background:#ffeadf;color:#de643c}\n.ins4-row-content h3{font-size:19px;letter-spacing:-.025em;color:#122f4d;font-weight:860;margin:0 0 7px}\n.ins4-row-content p{font-size:12px;line-height:1.68;color:#62788b;margin:0;max-width:460px}\n.ins4-row-arrow{font-size:22px;color:#4e7098;align-self:start;padding-top:8px}\n.ins4-workflow{position:relative;isolation:isolate;border-radius:22px;background:#0b203b;color:#fff;padding:66px 66px 54px;overflow:hidden}\n.ins4-workflow-spot{position:absolute;right:-13px;top:0;font-size:250px;line-height:.9;font-weight:900;letter-spacing:-.1em;color:rgba(255,255,255,.035);pointer-events:none;z-index:-1;white-space:nowrap}\n.ins4-workflow-heading{display:flex;justify-content:space-between;gap:35px;align-items:end;margin-bottom:58px}\n.ins4-workflow-kicker{font-size:11px;color:#81f5d6;font-weight:850;letter-spacing:.16em;margin-bottom:18px}\n.ins4-workflow-heading h2{font-size:clamp(45px,5vw,76px);color:#fff!important;font-weight:880;letter-spacing:-.065em;line-height:1.02;margin:0}\n.ins4-workflow-heading h2 em{font-family:Georgia,Times,serif;font-weight:500;color:#80f3d3}\n.ins4-workflow-heading p{font-size:14px;line-height:1.8;color:#b8cce1;max-width:355px;margin:0}\n.ins4-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;border-top:1px solid rgba(255,255,255,.19)}\n.ins4-step{padding:25px 13px 24px 0;border-right:1px solid rgba(255,255,255,.11)}\n.ins4-step:last-child{border-right:none}\n.ins4-step span{font-size:42px;font-weight:850;letter-spacing:-.07em;color:#74efd0;display:block;margin-bottom:31px}\n.ins4-step strong{display:block;color:#fff;font-size:16px;margin-bottom:9px}\n.ins4-step p{font-size:12px;line-height:1.68;color:#a7bed7;max-width:225px;margin:0}\n.ins4-bottom-cta{display:inline-flex;align-items:center;gap:38px;padding:15px 16px 15px 22px;border-radius:8px;background:#e7f5ff!important;color:#123760!important;font-size:13px;font-weight:850;margin-top:22px}\n.ins4-bottom-cta span{font-size:20px;color:#1748a4}\n.ins4-bottom-cta:hover{background:#ffffff!important}\n.ins4-footer{display:flex;align-items:center;justify-content:space-between;gap:15px;color:#76889b;font-size:10px;font-weight:750;letter-spacing:.08em;padding:28px 6px 20px}\n.ins4-footer b{color:#122e50;letter-spacing:.18em}\n@media(max-width:1220px){.ins4-hero-left{padding:27px 36px}.ins4-hero h1{font-size:clamp(55px,6vw,85px)}.ins4-hero-right{padding:27px 22px}.ins4-visual{min-height:400px}.ins4-capabilities{gap:46px}}\n@media(max-width:880px){.ins4-hero{grid-template-columns:1fr}.ins4-hero-left{padding:35px}.ins4-hero-main{padding:62px 0 64px}.ins4-hero h1{font-size:clamp(59px,9.4vw,90px)}.ins4-hero-right{min-height:550px}.ins4-visual{min-height:430px}.ins4-transformer{max-height:420px;width:min(75%,510px)}.ins4-capabilities{grid-template-columns:1fr;gap:37px;padding:75px 18px}.ins4-section-intro p{max-width:650px}.ins4-workflow{padding:50px 36px}.ins4-ticker{grid-template-columns:1fr;gap:12px}.ins4-ticker>div{justify-content:flex-start;padding:0 17px}}\n@media(max-width:580px){.ins4-header{height:69px}.ins4-brandmark{width:36px;height:36px}.ins4-brandwords b{font-size:16px}.ins4-brandwords small{font-size:7px;letter-spacing:.055em}.ins4-nav{gap:0}.ins4-nav>a:not(.ins4-nav-cta){display:none}.ins4-nav-cta{padding:10px;font-size:10px;gap:6px;min-height:40px}.ins4-nav-cta span{font-size:15px}.ins4-hero{border-radius:14px}.ins4-hero-left{padding:23px 21px 25px}.ins4-topline{font-size:8px;gap:8px}.ins4-topline-num{font-size:8px}.ins4-dash{width:13px}.ins4-hero-main{padding:44px 0 48px}.ins4-edition{font-size:8px;letter-spacing:.11em}.ins4-hero h1{font-size:clamp(51px,13.7vw,76px);margin-bottom:24px}.ins4-lead{font-size:13.5px;line-height:1.76}.ins4-action-row{gap:12px}.ins4-start{min-height:52px;padding-left:16px;gap:15px;font-size:12px}.ins4-discover{font-size:11px}.ins4-hero-bottom{font-size:8px;line-height:1.5;gap:8px;padding-top:15px}.ins4-hero-right{padding:20px 17px;min-height:460px}.ins4-right-top{font-size:8px;letter-spacing:.05em}.ins4-real-photo{font-size:7px;padding:6px}.ins4-visual{min-height:350px}.ins4-transformer{width:min(100%,420px);max-height:370px}.ins4-visual-no{font-size:125px}.ins4-image-caption{bottom:1%;left:0}.ins4-image-caption strong{font-size:11px}.ins4-image-caption span{font-size:8px}.ins4-right-bottom{padding-top:13px;align-items:start}.ins4-right-data-label{font-size:8px;line-height:1.4}.ins4-data-list{gap:4px;justify-content:flex-end}.ins4-data-list span{font-size:8px;padding:6px}.ins4-ticker{padding:17px 10px;margin:0 8px}.ins4-ticker>div{font-size:9px}.ins4-capabilities{padding:63px 7px}.ins4-section-intro h2{font-size:42px}.ins4-section-intro h2 em{white-space:normal}.ins4-section-intro p{font-size:13px}.ins4-cap-row{grid-template-columns:15px 43px minmax(0,1fr);gap:10px;padding:24px 0}.ins4-row-icon{height:43px;width:43px;font-size:24px}.ins4-row-content h3{font-size:16px}.ins4-row-content p{font-size:11.5px}.ins4-row-arrow{display:none}.ins4-workflow{padding:36px 23px;border-radius:15px}.ins4-workflow-heading{display:block;margin-bottom:32px}.ins4-workflow-heading h2{font-size:51px}.ins4-workflow-heading p{margin-top:23px;font-size:12px}.ins4-steps{grid-template-columns:1fr 1fr;gap:5px}.ins4-step{padding:22px 5px 17px 0}.ins4-step:nth-child(2){border-right:none}.ins4-step span{font-size:31px;margin-bottom:18px}.ins4-step strong{font-size:13px}.ins4-step p{font-size:10px}.ins4-footer{display:block;font-size:9px}.ins4-footer span{display:block;margin-bottom:9px}}\n@media(prefers-reduced-motion:reduce){.ins4-shell *,.ins4-shell *::before,.ins4-shell *::after{animation:none!important;transition:none!important}}\n\n\n/* HD PHOTO FINISH — photographic edit, not a synthetic transformer */\n.ins4-hero-right{\n  background:\n    radial-gradient(ellipse 75% 60% at 52% 46%,rgba(90,163,242,.52) 0%,rgba(39,115,219,.18) 55%,transparent 80%),\n    linear-gradient(145deg,#0c337b 2%,#1552b3 53%,#2474db 100%);\n}\n.ins4-visual{overflow:visible;}\n.ins4-visual::before{\n  content:"";position:absolute;inset:10% 5% 5%;z-index:0;pointer-events:none;\n  background:radial-gradient(ellipse 55% 52% at 52% 45%,rgba(171,219,255,.36) 0%,rgba(95,169,237,.12) 58%,transparent 86%);\n  filter:blur(12px);\n}\n.ins4-visual::after{\n  content:"";position:absolute;z-index:1;pointer-events:none;bottom:7%;left:21%;width:60%;height:12%;border-radius:50%;\n  background:radial-gradient(ellipse at center,rgba(4,20,67,.56),rgba(5,28,83,.12) 60%,transparent 82%);\n  filter:blur(11px);\n}\n.ins4-transformer{\n  z-index:3;width:min(106%,570px);max-height:525px;\n  filter:drop-shadow(10px 30px 28px rgba(2,20,61,.38));\n  image-rendering:auto;\n  transform:translateY(-4px);\n}\n.ins4-transformer:hover{transform:translateY(-9px) scale(1.012)}\n.ins4-orbit-outer{border-color:rgba(204,237,255,.28);}\n.ins4-orbit-inner{border-style:dashed;border-color:rgba(223,242,255,.17);}\n.ins4-image-caption{bottom:1%;left:1%;border-radius:0 8px 8px 0;background:rgba(7,36,94,.6);box-shadow:0 10px 30px rgba(1,20,63,.15)}\n.ins4-right-top{position:relative;z-index:4;}\n.ins4-real-photo{background:rgba(9,43,111,.3);backdrop-filter:blur(5px);}\n@media(max-width:880px){.ins4-transformer{width:min(88%,550px);max-height:450px}}\n@media(max-width:580px){.ins4-transformer{width:min(103%,440px);max-height:385px}.ins4-visual::after{bottom:9%}}\n\n\n/* MOBILE MATCH REFINEMENT — make phone layout feel closer to desktop composition */\n@media(max-width:580px){\n  .ins4-shell{padding:0 2px}\n  .ins4-header{height:66px;padding:0 2px 0 0;margin-bottom:10px}\n  .ins4-brand{gap:10px;min-width:0}\n  .ins4-brandwords{min-width:0}\n  .ins4-brandwords b{font-size:15px;letter-spacing:.15em}\n  .ins4-brandwords small{font-size:6.5px;letter-spacing:.08em;white-space:nowrap}\n  .ins4-nav-cta{padding:10px 12px;font-size:10px;gap:8px;min-height:40px;border-radius:8px;box-shadow:0 8px 18px rgba(9,30,56,.15)}\n\n  .ins4-hero{border-radius:18px;grid-template-columns:1fr;box-shadow:0 14px 38px rgba(26,58,91,.09)}\n  .ins4-hero-left{padding:20px 18px 18px}\n  .ins4-topline{font-size:8px;gap:8px;letter-spacing:.09em}\n  .ins4-topline-num{font-size:8px}\n  .ins4-dash{width:14px;height:3px}\n  .ins4-hero-main{padding:22px 0 18px}\n  .ins4-edition{font-size:8px;letter-spacing:.14em;margin-bottom:14px}\n  .ins4-hero h1{font-size:46px;line-height:.92;letter-spacing:-.075em;margin-bottom:18px;max-width:290px}\n  .ins4-lead{font-size:13.5px;line-height:1.72;max-width:none;margin:0 0 20px}\n  .ins4-action-row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:12px}\n  .ins4-start{min-height:50px;padding:0 12px 0 18px;gap:12px;font-size:13px;border-radius:10px;box-shadow:0 10px 22px rgba(239,102,59,.24)}\n  .ins4-start span{width:30px;height:30px;font-size:17px}\n  .ins4-discover{font-size:11px;padding:10px 0 6px;justify-self:start}\n  .ins4-hero-bottom{font-size:8px;line-height:1.55;gap:8px;padding-top:16px;margin-top:4px}\n\n  .ins4-hero-right{padding:15px 14px 16px;min-height:0;border-top:1px solid rgba(255,255,255,.08)}\n  .ins4-right-top{font-size:8px;letter-spacing:.05em;margin-bottom:12px}\n  .ins4-real-photo{font-size:7px;padding:6px 8px;border-radius:999px}\n  .ins4-visual{min-height:308px;border-radius:14px;padding:16px 12px 48px;overflow:hidden}\n  .ins4-visual-no{font-size:112px;right:3%;top:7%}\n  .ins4-transformer{width:min(98%,360px);max-height:300px;transform:translateY(0)}\n  .ins4-transformer:hover{transform:none}\n  .ins4-corner-mark{width:24px;height:24px}\n  .ins4-image-caption{left:3%;bottom:4%;padding:6px 10px;border-left-width:2px}\n  .ins4-image-caption strong{font-size:11px}\n  .ins4-image-caption span{font-size:7px}\n  .ins4-right-bottom{padding-top:14px;display:block}\n  .ins4-right-data-label{display:block;margin-bottom:10px;font-size:8px;line-height:1.5}\n  .ins4-data-list{gap:6px;justify-content:flex-start}\n  .ins4-data-list span{font-size:8px;padding:7px 8px;min-width:54px;text-align:center}\n\n  .ins4-ticker{margin:0 6px;padding:16px 14px;border-radius:0 0 16px 16px;gap:10px}\n  .ins4-ticker>div{justify-content:flex-start;font-size:9px;letter-spacing:.11em;padding:0 6px}\n  .ins4-ticker-star{font-size:17px}\n\n  .ins4-capabilities{padding:52px 6px 60px;gap:28px}\n  .ins4-section-kicker{margin-bottom:18px}\n  .ins4-section-intro h2{font-size:38px;line-height:1.02;margin:0 0 16px}\n  .ins4-section-intro p{font-size:13px;line-height:1.8}\n  .ins4-rows{border-top:none;display:grid;gap:12px}\n  .ins4-cap-row{grid-template-columns:18px 44px minmax(0,1fr);gap:12px;padding:18px 14px;background:#fff;border:1px solid #dfe7ef;border-radius:16px;box-shadow:0 8px 22px rgba(15,42,78,.05)}\n  .ins4-row-index{padding-top:8px}\n  .ins4-row-arrow{display:none}\n  .ins4-row-content h3{font-size:16px;margin-bottom:6px}\n  .ins4-row-content p{font-size:11.5px;line-height:1.62}\n\n  .ins4-workflow{padding:30px 18px 26px;border-radius:18px}\n  .ins4-workflow-spot{font-size:148px;right:-6px;top:8px}\n  .ins4-workflow-heading{display:block;margin-bottom:26px}\n  .ins4-workflow-kicker{font-size:10px;margin-bottom:12px}\n  .ins4-workflow-heading h2{font-size:44px;line-height:.97}\n  .ins4-workflow-heading p{margin-top:14px;font-size:12px;line-height:1.75;max-width:none}\n  .ins4-steps{grid-template-columns:1fr 1fr;gap:10px;border-top:1px solid rgba(255,255,255,.16);padding-top:10px}\n  .ins4-step{padding:14px 8px 12px 0;border-right:none;border-bottom:1px solid rgba(255,255,255,.08)}\n  .ins4-step:nth-last-child(-n+2){border-bottom:none}\n  .ins4-step span{font-size:30px;margin-bottom:12px}\n  .ins4-step strong{font-size:13px;margin-bottom:6px}\n  .ins4-step p{font-size:10.5px;line-height:1.58}\n  .ins4-bottom-cta{width:100%;justify-content:space-between;margin-top:18px;padding:14px 14px 14px 18px;border-radius:10px;font-size:12px;gap:12px}\n  .ins4-bottom-cta span{font-size:18px}\n\n  .ins4-footer{display:block;padding:24px 6px 16px;font-size:9px;line-height:1.6}\n  .ins4-footer span{display:block;margin-bottom:6px}\n}\n@media(max-width:380px){\n  .ins4-hero h1{font-size:42px;max-width:260px}\n  .ins4-visual{min-height:286px}\n  .ins4-transformer{width:min(100%,330px);max-height:278px}\n  .ins4-section-intro h2{font-size:34px}\n  .ins4-workflow-heading h2{font-size:40px}\n}\n\n\n/* Mobile photo polish — keep V2 editorial proportions, add a clean metallic light. */\n@media(max-width:580px){\n  .ins4-hero-right{\n    background:\n      radial-gradient(ellipse 92% 66% at 52% 49%,rgba(127,190,246,.32) 0%,rgba(28,104,211,.12) 60%,transparent 90%),\n      linear-gradient(142deg,#103b89 0%,#1350b3 51%,#2374d8 100%);\n  }\n  .ins4-visual{isolation:isolate;min-height:318px;padding:12px 6px 46px;border-radius:18px;overflow:hidden;}\n  /* Highlight existing photographic edges without altering the transformer itself. */\n  .ins4-visual::before{\n    inset:9% 3% 9%;opacity:.95;filter:blur(15px);\n    background:radial-gradient(ellipse 56% 54% at 50% 45%,rgba(201,231,255,.44),rgba(128,194,248,.17) 54%,transparent 82%);\n  }\n  .ins4-visual::after{\n    bottom:10%;left:17%;width:66%;height:10%;\n    background:radial-gradient(ellipse at center,rgba(3,22,70,.55),rgba(2,30,90,.08) 65%,transparent 88%);\n    filter:blur(12px);\n  }\n  .ins4-transformer{\n    width:min(97%,380px);max-height:310px;\n    filter:drop-shadow(4px 16px 16px rgba(1,20,54,.28)) drop-shadow(0 3px 6px rgba(1,19,52,.19));\n    transform:translateY(-2px);\n  }\n  .ins4-transformer:hover{transform:translateY(-2px);}\n  .ins4-orbit-outer{border-color:rgba(195,232,255,.3);}\n  .ins4-orbit-inner{border-color:rgba(228,247,255,.2);}\n  .ins4-image-caption{z-index:6;bottom:3%;left:3%;background:rgba(9,38,91,.78);}\n}\n@media(max-width:380px){\n  .ins4-visual{min-height:290px;}\n  .ins4-transformer{width:min(98%,340px);max-height:283px;}\n}\n\n\n/* V3 / genuine photo focus and cross-browser legibility */\n.ins4-shell, .ins4-shell * { -webkit-text-size-adjust:100%; text-size-adjust:100%; }\n.ins4-shell a:focus-visible{outline:3px solid #f8a45e;outline-offset:3px}\n.ins4-visual{\n  isolation:isolate;\n  background:radial-gradient(ellipse 62% 60% at 51% 48%, rgba(225,243,255,.41) 0%,rgba(121,191,246,.18) 55%,transparent 80%);\n}\n.ins4-visual::before{\n  background:radial-gradient(circle at 50% 46%,rgba(231,249,255,.38),rgba(97,167,255,.12) 55%,transparent 75%);\n  filter:blur(14px);\n}\n.ins4-transformer{\n  filter:brightness(1.08) contrast(1.115) saturate(.96) drop-shadow(9px 21px 18px rgba(1,18,57,.34));\n  -webkit-backface-visibility:hidden;\n  backface-visibility:hidden;\n}\n.ins4-right-top, .ins4-right-bottom{position:relative;z-index:5}\n@media(max-width:580px){\n  .ins4-hero-right{background:\n    radial-gradient(ellipse 95% 64% at 54% 52%,rgba(88,157,238,.40),transparent 75%),\n    linear-gradient(145deg,#0B347C 0%,#1353AB 55%,#206ED3 100%)}\n  .ins4-visual{min-height:330px;overflow:hidden;\n    background:radial-gradient(ellipse 73% 64% at 50% 45%,rgba(224,245,255,.44),rgba(103,175,255,.1) 57%,transparent 82%)}\n  .ins4-transformer{width:min(100%,370px);max-height:323px;filter:brightness(1.1) contrast(1.13) saturate(.98) drop-shadow(6px 16px 14px rgba(0,22,66,.39))}\n  .ins4-real-photo{border-color:rgba(255,255,255,.60);color:#fff}\n  .ins4-right-data-label,.ins4-data-list span{color:#fff}\n  .ins4-hero h1{overflow-wrap:normal;word-break:normal}\n}\n@media(max-width:370px){\n  .ins4-transformer{max-height:293px;width:min(100%,345px)}\n  .ins4-visual{min-height:303px}\n}\n\n/* Small release mark helps distinguish this installation from an old running localhost. */\n.ins4-release{vertical-align:middle;margin-left:3px;display:inline-block;padding:3px 5px;border-radius:4px;background:#DFF2FF;color:#1857A0!important;font-family:Inter,Arial,sans-serif;font-style:normal;font-size:9px;letter-spacing:.03em;font-weight:800;transform:translateY(-2px)}\n@media(max-width:580px){.ins4-release{font-size:8px;padding:2px 4px}}\n'
_INSIGHT_LANDING_HTML = '<div class="ins4-shell" id="top">\n  <header class="ins4-header">\n    <a href="#top" class="ins4-brand" aria-label="INSIGHT home">\n      <span class="ins4-brandmark" aria-hidden="true"><svg width="27" height="27" viewBox="0 0 27 27" fill="none"><path d="M15 2L6 15h8l-2 10 10-15h-8l1-8Z" stroke="currentColor" stroke-width="2.4" stroke-linejoin="round"/></svg></span>\n      <span class="ins4-brandwords"><b>INSIGHT <span class="ins4-release">V4</span></b><small>TRANSFORMER CONDITION INTELLIGENCE</small></span>\n    </a>\n    <nav class="ins4-nav" aria-label="Main navigation">\n      <a href="#platform">The platform</a>\n      <a href="#workflow">How it works</a>\n      <a class="ins4-nav-cta" href="?auth=1" target="_self">Enter workspace <span aria-hidden="true">↗</span></a>\n    </nav>\n  </header>\n\n  <main>\n    <section class="ins4-hero" id="home" aria-labelledby="ins4-headline">\n      <div class="ins4-hero-left">\n        <div class="ins4-topline"><span class="ins4-dash"></span> A NEW PERSPECTIVE ON ASSET HEALTH <span class="ins4-topline-num">01 / 03</span></div>\n        <div class="ins4-hero-main">\n          <div class="ins4-edition">CONDITION MONITORING / REIMAGINED</div>\n          <h1 id="ins4-headline">See beyond<br>the <span>oil.</span></h1>\n          <p class="ins4-lead">Transform test data into a clearer understanding of transformer condition, fault indicators, and maintenance priorities.</p>\n          <div class="ins4-action-row">\n            <a href="?auth=1" target="_self" class="ins4-start">Get Started <span aria-hidden="true">↗</span></a>\n            <a href="#platform" class="ins4-discover">Discover INSIGHT <span aria-hidden="true">↓</span></a>\n          </div>\n        </div>\n        <div class="ins4-hero-bottom"><span class="ins4-tick"></span> FROM OIL TESTING TO ACTIONABLE INSIGHT <span class="ins4-hero-bottom-arrow" aria-hidden="true">↗</span></div>\n      </div>\n\n      <div class="ins4-hero-right">\n        <div class="ins4-right-grid" aria-hidden="true"></div>\n        <div class="ins4-right-top"><span>FIG. 01 — DISTRIBUTION TRANSFORMER</span><span class="ins4-real-photo"><span></span> REFERENCE PHOTO</span></div>\n        <div class="ins4-visual">\n          <div class="ins4-orbit ins4-orbit-outer" aria-hidden="true"></div>\n          <div class="ins4-orbit ins4-orbit-inner" aria-hidden="true"></div>\n          <div class="ins4-visual-no" aria-hidden="true">01</div>\n          <img src="__INSIGHT_TRANSFORMER_PHOTO__" class="ins4-transformer" alt="Foto asli transformator distribusi berisolasi minyak yang diberikan pengguna" loading="eager" decoding="async">\n          <div class="ins4-corner-mark ins4-corner-a" aria-hidden="true"></div><div class="ins4-corner-mark ins4-corner-b" aria-hidden="true"></div>\n          <div class="ins4-image-caption"><span>Oil-immersed</span><strong>Distribution Transformer</strong></div>\n        </div>\n        <div class="ins4-right-bottom">\n          <span class="ins4-right-data-label">CORE DATA INPUTS</span>\n          <div class="ins4-data-list"><span>01 / BDV</span><span>02 / WC</span><span>03 / DGA</span></div>\n        </div>\n      </div>\n    </section>\n\n    <div class="ins4-ticker" aria-label="Analysis stages">\n      <div><span class="ins4-ticker-star">✳</span> MEASURE THE CONDITION</div>\n      <div><span class="ins4-ticker-star">✳</span> INTERPRET THE SIGNALS</div>\n      <div><span class="ins4-ticker-star">✳</span> SUPPORT THE DECISION</div>\n    </div>\n\n    <section id="platform" class="ins4-capabilities" aria-labelledby="ins4-platform-heading">\n      <div class="ins4-section-intro">\n        <div class="ins4-section-kicker"><span>02</span> / WHAT INSIGHT DOES</div>\n        <h2 id="ins4-platform-heading">One platform.<br><em>Deeper perspective.</em></h2>\n        <p>Understand the condition behind the numbers. From laboratory measurements to a structured evaluation and clear maintenance guidance.</p>\n      </div>\n      <div class="ins4-rows">\n        <article class="ins4-cap-row"><div class="ins4-row-index">01</div><div class="ins4-row-icon ins4-icon-a" aria-hidden="true">◈</div><div class="ins4-row-content"><h3>Health assessment</h3><p>Evaluate measured parameters through the established indeks kesehatan scoring and weighting method.</p></div><div class="ins4-row-arrow" aria-hidden="true">↗</div></article>\n        <article class="ins4-cap-row"><div class="ins4-row-index">02</div><div class="ins4-row-icon ins4-icon-b" aria-hidden="true">△</div><div class="ins4-row-content"><h3>Gas diagnostics</h3><p>Interpret dissolved gas status and apply the Duval diagnostic method supported by the available data.</p></div><div class="ins4-row-arrow" aria-hidden="true">↗</div></article>\n        <article class="ins4-cap-row"><div class="ins4-row-index">03</div><div class="ins4-row-icon ins4-icon-c" aria-hidden="true">⌁</div><div class="ins4-row-content"><h3>Maintenance direction</h3><p>Review condition outputs, method-based recommendations, analysis history, and downloadable reports.</p></div><div class="ins4-row-arrow" aria-hidden="true">↗</div></article>\n      </div>\n    </section>\n\n    <section id="workflow" class="ins4-workflow" aria-labelledby="ins4-workflow-title">\n      <div class="ins4-workflow-spot" aria-hidden="true">INSIGHT</div>\n      <div class="ins4-workflow-heading"><div><div class="ins4-workflow-kicker">03 / THE WORKFLOW</div><h2 id="ins4-workflow-title">From sample<br>to <em>strategy.</em></h2></div><p>Each stage follows a traceable assessment flow, so results stay tied to the data and methods behind them.</p></div>\n      <div class="ins4-steps">\n        <div class="ins4-step"><span>01</span><strong>Input</strong><p>Enter data manually or upload an Excel file.</p></div>\n        <div class="ins4-step"><span>02</span><strong>Validate</strong><p>Review parameter availability and applicable methods.</p></div>\n        <div class="ins4-step"><span>03</span><strong>Analyze</strong><p>Calculate health and gas diagnostics.</p></div>\n        <div class="ins4-step"><span>04</span><strong>Decide</strong><p>Review outcomes, recommendations and reports.</p></div>\n      </div>\n      <a href="?auth=1" target="_self" class="ins4-bottom-cta">Open assessment workspace <span>↗</span></a>\n    </section>\n    <footer class="ins4-footer"><span><b>INSIGHT</b> — TRANSFORMER HEALTH INTELLIGENCE</span><span>BUILT FOR EVIDENCE-BASED CONDITION ASSESSMENT</span></footer>\n  </main>\n</div>\n'
