@st.cache_data(show_spinner=False)
def _insight_embedded_hero_data_uri():
    """Decode the exact V3 WebP bytes to a browser data URL (cached)."""
    payload = "".join(_INSIGHT_HERO_WEBP_B85.split())
    photo_bytes = _insight_base64.b85decode(payload.encode("ascii"))
    return "data:image/webp;base64," + _insight_base64.b64encode(photo_bytes).decode("ascii")


