def _interactive_3d_statuses(record):
    record = record or {}
    # The 3D color is explicitly HI-based. A descriptive multi-indicator label is
    # not a new validated risk/severity class and must not be color-classified as such.
    hi_condition = normalize_condition_label(record.get("Calculated Condition", "")) or "Not available"
    condition = str(record.get("Overall Condition", "")) or f"HI {hi_condition}"
    dga_ind = str(record.get("DGA Indication", "") or "").strip()
    duval_fault = str(record.get("Duval Fault Type", "") or "").strip()
    dominant = str(record.get("Dominant Factor", "") or "").strip()
    bdv = record.get("BDV", "")
    wc = record.get("Water Content", "")
    hi = record.get("HI (%)", "")

    def condition_status(value):
        v = str(value or "").lower()
        if "very poor" in v or v == "poor":
            return "critical"
        if "fair" in v:
            return "warning"
        if "good" in v or "very good" in v:
            return "good"
        return "neutral"

    overall = condition_status(hi_condition)
    dga_status = "neutral"
    if dga_ind:
        dl = dga_ind.lower()
        dga_status = "critical" if any(x in dl for x in ["critical", "severe", "high energy", "arcing", "t3"]) else "warning" if any(x in dl for x in ["abnormal", "fault", "warning", "elevated", "high"]) else "good"
    if duval_fault and duval_fault.lower() not in {"normal", "not available"} and "required" not in duval_fault.lower():
        fl = duval_fault.lower()
        dga_status = "critical" if any(x in fl for x in ["high energy", "arcing", "t3"]) else "warning"

    if str(record.get("Duval Diagnosis Zone",record.get("Duval Zone","")) or "").strip().upper() in {"D2", "DT", "T3"}:
        dga_status = "critical"  # same critical zones used by get_recommendation()
    try:
        ieee_n = int(float(record.get("IEEE TDCG Condition", "")))
    except Exception:
        ieee_n = None
    ieee_txt = f" • DGA Status {ieee_n}" if ieee_n else ""
    if ieee_n:
        _ieee_status = {1: "good", 2: "warning", 3: "warning", 4: "critical"}.get(ieee_n, "neutral")
        _rank = {"neutral": 0, "good": 1, "warning": 2, "critical": 3}
        if _rank[_ieee_status] > _rank[dga_status]:
            dga_status = _ieee_status

    oil_status = overall
    dom = dominant.lower()
    if any(x in dom for x in ["water", "bdv", "oil", "moisture", "acidity"]):
        oil_status = "warning" if overall == "good" else overall

    return {
        "main_tank": {"label":"Main Tank","status":overall,"title":"HI-based color (not composite severity)","evidence":f"Health Index: {hi if hi not in [None, ''] else '—'}% • Kategori HI: {hi_condition} • Overall: {condition}"},
        "active_part": {"label":"Active Part / DGA","status":dga_status,"title":"DGA / dissolved-gas indication","evidence":f"DGA: {dga_ind or 'Not available'}{(' • Duval: ' + duval_fault) if duval_fault else ''}{ieee_txt}"},
        "oil": {"label":"Insulation / Oil","status":oil_status,"title":"Oil-condition evidence","evidence":f"BDV: {bdv if bdv not in [None, ''] else '—'} kV • Water Content: {wc if wc not in [None, ''] else '—'} ppm"},
        "cooling": {"label":"Cooling / Radiator","status":"neutral","title":"No direct cooling-component diagnosis","evidence":"Current assessment data do not contain a radiator-specific diagnostic test."},
        "bushing": {"label":"Bushing","status":"neutral","title":"No direct bushing diagnosis","evidence":"Current assessment data do not contain a bushing-specific diagnostic test."},
        "conservator": {"label":"Conservator","status":"neutral","title":"No direct conservator diagnosis","evidence":"The 3D model visualizes the component but does not infer a failure from BDV/WC/DGA."},
    }

def _status_color(status):
    return {
        "good": "#18A775",
        "warning": "#F1A21A",
        "critical": "#E45463",
        "neutral": "#8FA3B7",
    }.get(status, "#8FA3B7")


def _component_status_data(record):
    data = _interactive_3d_statuses(record or {}) if "_interactive_3d_statuses" in globals() else {}
    if not data:
        # Safe fallback if the richer helper is not present.
        condition = normalize_condition_label((record or {}).get("Overall Condition", "")) or "Not available"
        status = "good" if condition in ["Very Good", "Good"] else "warning" if condition == "Fair" else "critical" if condition in ["Poor", "Very Poor"] else "neutral"
        data = {
            "main_tank": {"label":"Main Tank","status":status,"title":"Overall transformer condition","evidence":f"Condition: {condition}"},
            "active_part": {"label":"Active Part","status":"neutral","title":"DGA indication","evidence":"Select an assessment with DGA data for a diagnostic indication."},
            "oil": {"label":"Insulation / Oil","status":status,"title":"Oil-condition evidence","evidence":f"BDV: {(record or {}).get('BDV','—')} kV • Water Content: {(record or {}).get('Water Content','—')} ppm"},
            "cooling": {"label":"Cooling / Radiator","status":"neutral","title":"No direct cooling-component test","evidence":"No radiator-specific measurement is included."},
            "bushing": {"label":"Bushing","status":"neutral","title":"No direct bushing test","evidence":"No bushing-specific measurement is included."},
            "conservator": {"label":"Conservator","status":"neutral","title":"No direct conservator test","evidence":"No conservator-specific measurement is included."},
        }
    return data


def _box_mesh(x0,x1,y0,y1,z0,z1,color,name,opacity=1.0,hover_text=""):
    xs=[x0,x1,x1,x0,x0,x1,x1,x0]
    ys=[y0,y0,y1,y1,y0,y0,y1,y1]
    zs=[z0,z0,z0,z0,z1,z1,z1,z1]
    i=[0,0,0,1,1,4,4,3,3,2,2,7]
    j=[1,2,4,2,5,5,6,0,7,6,3,6]
    k=[2,4,5,6,2,6,7,7,4,5,6,3]
    return go.Mesh3d(x=xs,y=ys,z=zs,i=i,j=j,k=k,color=color,opacity=opacity,name=name,hovertemplate=hover_text or f"<b>{name}</b><extra></extra>",showlegend=False,flatshading=True,lighting=dict(ambient=.65,diffuse=.85,specular=.2,roughness=.72))


def _cylinder_mesh(cx,cy,cz,radius,height,axis="y",color="#6B7781",name="Component",segments=28,opacity=1.0):
    import math
    verts=[]
    for level in [0,1]:
        offset=-height/2 if level==0 else height/2
        for s in range(segments):
            a=2*math.pi*s/segments
            xx=cx+radius*math.cos(a)
            yy=cy+radius*math.sin(a)
            zz=cz+offset
            if axis=="x":
                xx=cx+offset; yy=cy+radius*math.cos(a); zz=cz+radius*math.sin(a)
            elif axis=="z":
                xx=cx+radius*math.cos(a); yy=cy+radius*math.sin(a); zz=cz+offset
            else:
                xx=cx+radius*math.cos(a); yy=cy+offset; zz=cz+radius*math.sin(a)
            verts.append((xx,yy,zz))
    # cap centers
    verts.append((cx-height/2 if axis=="x" else cx, cy-height/2 if axis=="y" else cy, cz-height/2 if axis=="z" else cz))
    verts.append((cx+height/2 if axis=="x" else cx, cy+height/2 if axis=="y" else cy, cz+height/2 if axis=="z" else cz))
    x=[v[0] for v in verts]; y=[v[1] for v in verts]; z=[v[2] for v in verts]
    ii=[];jj=[];kk=[]
    for s in range(segments):
        n=(s+1)%segments
        a=s;b=n;c=segments+s;d=segments+n
        ii += [a,a,c]; jj += [n,c,d]; kk += [c,d,n]
        ii.append(2*segments); jj.append(n); kk.append(s)
        ii.append(2*segments+1); jj.append(segments+s); kk.append(segments+n)
    return go.Mesh3d(x=x,y=y,z=z,i=ii,j=jj,k=kk,color=color,opacity=opacity,name=name,showlegend=False,hovertemplate=f"<b>{name}</b><extra></extra>",lighting=dict(ambient=.65,diffuse=.85,specular=.22,roughness=.65))


def render_dga_status_panels(record, part="both"):
    """Explicit 2019 screening only. Historical V4 results are labeled LEGACY and not reinterpreted."""
    record=record or {}
    modern=str(record.get("Calculation Version","")).startswith(("INSIGHT-scientific-v5", "INSIGHT-scientific-v6"))
    gases={key:record.get(key,"") for key in IEEE2019_GAS_NAMES}
    complete=valid_gas_values(list(gases.values()))
    if not complete:
        st.info("DGA: tujuh data gas numerik belum tersedia/valid.")
        return
    tdcg=sum(to_number(gases[k]) for k in ("H2","CH4","C2H6","C2H4","C2H2","CO"))
    if not modern:
        st.warning("Rekaman lama tanpa penanda metode IEEE 2019: jangan samakan dengan skrining DGA Status V6.")
        return
    evaluation=ieee_dga_status_2019(
        gases, o2_n2_ratio=(to_number(record.get("O2/N2 Ratio"))
                             if is_numeric_available(record.get("O2/N2 Ratio")) else None),
    )
    n=evaluation["status"]
    note=evaluation["note"]
    advice,_=ieee_condition_action(n)
    basis=evaluation["norm_basis"]
    if part in ("cards","both"):
        st.markdown('<div style="font-weight:800;color:var(--text);margin:4px 0 10px">DGA STATUS — IEEE C57.104-2019</div>',unsafe_allow_html=True)
        ca="#18A775" if n==1 else "#F1A21A" if n==2 else "#E45463"
        items=[("DGA Status",f"Status {n}","Provisional screening; verify trend and samples",ca),
               ("TDCG (informative)",f"{tdcg:.0f} ppm","Not a 4-condition DGA status threshold","#2F78F6"),
               ("Selected Duval",f"{record.get('Duval Method','Not Available')} — {record.get('Duval Diagnosis Zone','-')}",record.get("Duval Diagnosis Type", ""),"#0E9F88")]
        cards=[]
        for title,value,desc,color in items:
            cards.append(f'<div style="padding:13px;border:1px solid var(--border);border-left:5px solid {color};border-radius:12px;background:var(--card)"><div style="font-size:10px;color:var(--muted);font-weight:750">{escape(str(title))}</div><div style="font-size:15px;color:var(--text);font-weight:850;margin-top:6px">{escape(str(value))}</div><div style="font-size:11px;color:var(--muted);margin-top:5px">{escape(str(desc))}</div></div>')
        st.markdown('<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px">'+''.join(cards)+'</div>',unsafe_allow_html=True)
        st.caption(f"{basis}. {note}. {advice}")
    if part in ("table","both"):
        limits=IEEE2019_LEVELS["o2_high_unknown"]
        rows=[]
        for gas in IEEE2019_GAS_NAMES:
            value=to_number(gases[gas]);lo=limits["t1"][gas];hi=limits["t2"][gas]
            state="High" if value>=hi else "Elevated" if value>=lo else "Low"
            rows.append({"Gas":gas,"Value (ppm)":value,"Table 1":lo,"Table 2":hi,"2019 Level":state})
        st.dataframe(pd.DataFrame(rows),hide_index=True,use_container_width=True)


def render_interactive_transformer_3d_plotly(record=None, show_dga=True):
    """Native Plotly 3D transformer view: no external JS/CDN is required."""
    record = record or {}
    status_data = _component_status_data(record)
    labels = list(status_data.keys())
    label_map = {k:v["label"] for k,v in status_data.items()}
    default_key = "main_tank"
    if "3d_selected_component" not in st.session_state:
        st.session_state["3d_selected_component"] = default_key
    selected_key = st.selectbox(
        "Inspect component",
        labels,
        index=labels.index(st.session_state["3d_selected_component"]) if st.session_state["3d_selected_component"] in labels else 0,
        format_func=lambda k: label_map[k],
        key="transformer_3d_component_picker",
    )
    st.session_state["3d_selected_component"] = selected_key
    interior = st.checkbox("Interior / cutaway view", value=False, key="transformer_3d_interior")

    info = status_data[selected_key]
    status = info.get("status","neutral")
    c = _status_color(status)
    st.markdown(
        f'<div style="margin:4px 0 12px;padding:12px 14px;border:1px solid var(--border);border-radius:13px;background:var(--card);">'
        f'<div style="font-size:10px;text-transform:uppercase;letter-spacing:1.1px;color:var(--muted);font-weight:800">{escape(info.get("title","Component inspection"))}</div>'
        f'<div style="display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:4px">'
        f'<div style="font-size:17px;font-weight:800;color:var(--text)">{escape(info.get("label","Component"))}</div>'
        f'<span style="font-size:10px;font-weight:800;color:{c};background:{c}18;padding:5px 9px;border-radius:999px">{escape(status.title() if status != "neutral" else "No direct diagnosis")}</span>'
        f'</div><div style="font-size:10px;color:var(--muted);margin-top:7px;line-height:1.5">{escape(info.get("evidence",""))}</div></div>',
        unsafe_allow_html=True,
    )


    # ---- Fault location summary (which component is abnormal) ----
    _rec = record or {}
    def _meaningful(v):
        v = str(v or "").strip()
        return v if v and v.lower() not in {"normal", "not available", "nan", "none", "-"} and "required" not in v.lower() else ""
    _duval = _meaningful(_rec.get("Duval Fault Type", ""))
    _dga = _meaningful(_rec.get("DGA Indication", ""))
    _fault_hint = {
        "active_part": (_dga or _duval) + (f"; IEEE Cond. {_rec.get('IEEE TDCG Condition')}" if str(_rec.get("IEEE TDCG Condition", "")).strip() not in ("", "None") else ""),
        "oil": f"BDV {_rec.get('BDV','—')} kV / WC {_rec.get('Water Content','—')} ppm",
        "main_tank": f"HI {_rec.get('HI (%)','—')}%",
        "cooling": "", "bushing": "", "conservator": "",
    }
    _status_word = {"critical": "Critical", "warning": "Warning", "good": "Good", "neutral": "No data"}
    _abnormal = [(k, v) for k, v in status_data.items() if v.get("status") in ("critical", "warning")]
    _abnormal.sort(key=lambda kv: 0 if kv[1]["status"] == "critical" else 1)
    if _abnormal:
        _chips = "".join(
            f'<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:6px">'
            f'<span style="font-size:10px;font-weight:800;color:#fff;background:{_status_color(v["status"])};padding:4px 9px;border-radius:999px">{_status_word[v["status"]].upper()}</span>'
            f'<span style="font-size:13px;font-weight:750;color:var(--text)">{escape(v["label"])}</span>'
            f'<span style="font-size:11px;color:var(--muted)">{escape(str(_fault_hint.get(k, "")))}</span></div>'
            for k, v in _abnormal
        )
        _head = "Komponen terindikasi gangguan"
    else:
        _chips = '<div style="font-size:12px;color:var(--muted);margin-top:6px">Tidak ada komponen yang terindikasi gangguan pada assessment ini. Komponen abu-abu = tidak ada data uji langsung.</div>'
        _head = "Status gangguan komponen"
    _legend = "".join(
        f'<span style="display:inline-flex;align-items:center;gap:5px;margin-right:12px;font-size:10px;color:var(--muted)">'
        f'<span style="width:9px;height:9px;border-radius:50%;background:{_status_color(k)};display:inline-block"></span>{lab}</span>'
        for k, lab in [("critical", "Critical / fault"), ("warning", "Warning"), ("good", "Good"), ("neutral", "No direct data")]
    )
    st.markdown(
        f'<div style="margin:0 0 12px;padding:13px 15px;border:1px solid var(--border);border-radius:13px;background:var(--card)">'
        f'<div style="font-size:10px;text-transform:uppercase;letter-spacing:1.1px;font-weight:800;color:var(--muted)">{_head}</div>'
        f'{_chips}<div style="margin-top:10px">{_legend}</div></div>',
        unsafe_allow_html=True,
    )


    if show_dga:
        render_dga_status_panels(record, part="cards")

    fig = go.Figure()
    # Platform
    fig.add_trace(_box_mesh(-5.5,5.5,-.2,.15,-3.5,3.5,"#D9E3EA","Foundation",.95))

    main_status=status_data["main_tank"]["status"]
    tank_color=_status_color(main_status)
    tank_opacity=.25 if interior else .97
    fig.add_trace(_box_mesh(-3.35,3.35,.15,4.35,-1.85,1.85,tank_color,"Main Tank",tank_opacity,
                            f"<b>Main Tank</b><br>Status: {main_status.title()}<extra></extra>"))
    fig.add_trace(_box_mesh(-3.5,3.5,4.35,4.63,-1.95,1.95,"#728795","Roof",.96))

    # Feet
    for x in (-2.45,2.45):
        for z in (-1.25,1.25):
            fig.add_trace(_box_mesh(x-.28,x+.28,.15,.8,z-.28,z+.28,"#4C5B65","Support foot",.98))

    # Radiators - front and back
    cool_status=status_data["cooling"]["status"]
    cool_color=_status_color(cool_status)
    if not interior:
        for x in [(-3.05+i*.43) for i in range(15)]:
            fig.add_trace(_box_mesh(x-.07,x+.07,.75,3.95,-2.27,-2.08,cool_color,"Radiator",.78))
            fig.add_trace(_box_mesh(x-.07,x+.07,.75,3.95,2.08,2.27,cool_color,"Radiator",.78))

    # Conservator
    cons=status_data["conservator"]["status"]
    fig.add_trace(_cylinder_mesh(.25,5.45,0,1.0,4.2,"x",_status_color(cons),"Conservator",36,.94))
    for x in (-.55,.7):
        fig.add_trace(_box_mesh(x-.12,x+.12,4.35,5.05,-.12,.12,"#566874","Conservator support",.95))

    # Bushings
    bush=status_data["bushing"]["status"]
    for x in (-2.1,-.7,.7,2.1):
        fig.add_trace(_cylinder_mesh(x,5.1,0,.35,.4,"y","#566874","Bushing base",28,.96))
        fig.add_trace(_cylinder_mesh(x,6.0,0,.24,1.5,"y",_status_color(bush),"Bushing",28,.9))
        fig.add_trace(_cylinder_mesh(x,6.85,0,.14,.34,"y","#8C6E3B","Bushing top",24,.98))

    # Side control box
    fig.add_trace(_box_mesh(3.35,3.72,1.8,3.0,-.55,.55,"#71828D","Control box",.95))

    # Interior components
    if interior:
        _ap = status_data["active_part"]["status"]
        _ap_bad = _ap in ("critical", "warning")
        fig.add_trace(_box_mesh(-1.25,1.25,1.1,4.0,-.48,.48,_status_color(_ap) if _ap_bad else "#8E7A43","Core (active part)" if not _ap_bad else f"Core - {_ap.upper()}",.9))
        for x,col in [(-.75,"#7C4C2C"),(0,"#B86C28"),(.75,"#7C4C2C")]:
            if _ap_bad:
                col = _status_color(_ap)
            fig.add_trace(_cylinder_mesh(x,2.55,0,.42,2.2,"y",col,"Winding",28,.84))
        oil_status=status_data["oil"]["status"]
        fig.add_trace(_box_mesh(-2.95,2.95,.5,4.05,-1.4,1.4,_status_color(oil_status),"Insulating Oil",.15))

    # Hotspot markers with explicit FAULT / WARNING / OK labels
    # anchors sit outside the geometry (in front of radiators) so they stay visible
    label_text_color = {"critical": "#E0334A", "warning": "#D98300", "good": "#13946A", "neutral": "#7E92A6"}
    anchors = {
        "main_tank":   (-2.4, 3.9, 2.55),
        "active_part": (0.0, 3.0, 2.55),
        "oil":         (2.4, 1.2, 2.55),
        "cooling":     (-3.9, 2.2, 2.55),
        "bushing":     (3.2, 6.3, 0.0),
        "conservator": (-3.2, 5.6, 0.0),
    }
    targets = {"active_part": (0.0, 3.0, 0.0), "oil": (0.0, 1.2, 0.0)}
    for key, (x, y, z) in anchors.items():
        sd = status_data.get(key, {"status": "neutral", "label": key})
        stt = sd.get("status", "neutral")
        col = _status_color(stt)
        name = sd.get("label", key)
        hint = _fault_hint.get(key, "")
        if stt == "critical":
            txt = f"<b>FAULT: {name}</b>" + (f" ({hint})" if hint else "")
        elif stt == "warning":
            txt = f"<b>WARNING: {name}</b>" + (f" ({hint})" if hint else "")
        elif stt == "good":
            txt = f"{name}: OK"
        else:
            txt = f"{name}: no data"
        abnormal = stt in ("critical", "warning")
        if abnormal:
            # glow halo behind the marker
            fig.add_trace(go.Scatter3d(x=[x], y=[y], z=[z], mode="markers", marker=dict(size=24, color=col, opacity=.28),
                                       hoverinfo="skip", showlegend=False))
            if key in targets:
                tx, ty, tz = targets[key]
                fig.add_trace(go.Scatter3d(x=[x, tx], y=[y, ty], z=[z, tz], mode="lines",
                                           line=dict(color=col, width=4, dash="dot"), hoverinfo="skip", showlegend=False))
        fig.add_trace(go.Scatter3d(
            x=[x], y=[y], z=[z], mode="markers+text", text=[txt], textposition="top center",
            textfont=dict(color=label_text_color.get(stt, "#7E92A6"), size=13 if abnormal else 11),
            marker=dict(size=11 if abnormal else 7, color=col, line=dict(width=2, color="#ffffff")),
            name=name,
            hovertemplate=f"<b>{name}</b><br>Status: {_status_word[stt]}<br>{sd.get('title','')}<br>{sd.get('evidence','')}<extra></extra>",
            showlegend=False))

    fig.update_layout(
        height=610,
        margin=dict(l=0,r=0,t=0,b=0),
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        scene=dict(
            bgcolor="rgba(0,0,0,0)",
            xaxis=dict(visible=False,showgrid=False,zeroline=False),
            yaxis=dict(visible=False,showgrid=False,zeroline=False),
            zaxis=dict(visible=False,showgrid=False,zeroline=False),
            aspectmode="manual",
            aspectratio=dict(x=1.5,y=1.0,z=1.05),
            camera=dict(eye=dict(x=1.55,y=1.15,z=.95),center=dict(x=0,y=.6,z=0)),
            dragmode="orbit",
        ),
        hoverlabel=dict(bgcolor="#ffffff",font=dict(color="#12213F",size=11,family="Inter,Arial")),
    )
    st.plotly_chart(fig,use_container_width=True,config={"displayModeBar":True,"displaylogo":False,"responsive":True,"modeBarButtonsToRemove":["lasso3d","select2d","lasso2d"]}, theme=None)

    if show_dga:
        render_dga_status_panels(record, part="table")
    if status_data["active_part"]["status"] in ("critical", "warning") and not interior:
        st.info("Indikasi gangguan DGA berada di bagian dalam (active part: core/winding). Aktifkan \"Interior / cutaway view\" untuk melihat bagian yang ditandai.")
    st.caption("Drag untuk memutar 3D • scroll/pinch untuk zoom • hover pada komponen untuk melihat indikasi. Interior View adalah visualisasi konseptual, bukan lokasi kerusakan fisik yang terukur.")

def dashboard_dataframe():
    if not st.session_state.history:
        return pd.DataFrame()
    df = pd.DataFrame([r for r in st.session_state.history
                       if str(r.get("Analysis Mode", "Capstone")) == "Capstone"])
    if df.empty:
        return df
    if "Username" in df.columns:
        df = df[df["Username"].astype(str) == str(st.session_state.username)].copy()
    if "HI (%)" not in df.columns and "HI IEEE (%)" in df.columns:
        df = df.rename(columns={"HI IEEE (%)":"HI (%)"})
    if "Time" in df.columns:
        df["Time"] = pd.to_datetime(df["Time"], errors="coerce")
    if "HI (%)" in df.columns:
        df["HI (%)"] = pd.to_numeric(df["HI (%)"], errors="coerce")
    return df

def render_dashboard():
    df = dashboard_dataframe()
    st.markdown('<div class="page-kicker">Overview</div>', unsafe_allow_html=True)
    st.markdown('<div class="page-title">Dashboard</div>', unsafe_allow_html=True)
    st.markdown('<div class="page-subtitle">Transformer condition summary based on Health Index analysis</div>', unsafe_allow_html=True)
    if df.empty:
        total = 0; avg_hi = 0; good = 0; attention = 0
    else:
        total = len(df)
        avg_hi = float(df["HI (%)"].dropna().mean()) if df["HI (%)"].notna().any() else 0
        good = int((df["HI (%)"] >= 70).sum())
        attention = int((df["HI (%)"] < 70).sum())
    m1,m2,m3,m4=st.columns(4)
    cards=[
        (m1,"▥","Total Assessments",f"{total}","Records", "Stored analysis records"),
        (m2,"♡","Average Health Index",f"{avg_hi:.1f}%","", "Average across all evaluations"),
        (m3,"⌁","Good Condition (HI ≥ 70%)",f"{good}","Records", f"{(good/total*100 if total else 0):.1f}% of total"),
        (m4,"!","Condition Requiring Attention",f"{attention}","Records", f"{(attention/total*100 if total else 0):.1f}% of total"),
    ]
    for col,icon,title,value,unit,sub in cards:
        with col:
            st.markdown(f'<div class="metric-card"><div class="metric-icon">{icon}</div><div class="metric-label">{title}</div><div class="metric-value">{value} <span style="font-size:13px;font-weight:500;color:var(--muted)">{unit}</span></div><div class="metric-sub">{sub}</div></div>',unsafe_allow_html=True)
    st.markdown("<div style='height:2px'></div>",unsafe_allow_html=True)
    c1,c2=st.columns([1,1.1])
    with c1:
        st.markdown('<div class="card"><div class="mini-title">Transformer Condition Distribution</div>',unsafe_allow_html=True)
        if df.empty:
            st.info("No analysis results yet. Start from Input / Upload Data.")
        else:
            h=df["HI (%)"].dropna()
            dist=pd.DataFrame({"Condition":["Very Good","Good","Fair","Poor","Very Poor"],"Count":[int((h>=85).sum()),int(((h>=70)&(h<85)).sum()),int(((h>=50)&(h<70)).sum()),int(((h>=30)&(h<50)).sum()),int((h<30).sum())]})
            fig=px.pie(dist,names="Condition",values="Count",hole=.58)
            fig.update_layout(height=310,margin=dict(l=10,r=10,t=10,b=10),legend=dict(orientation="v"))
            st.plotly_chart(fig,use_container_width=True,config={"displayModeBar":False}, theme=None)
        st.markdown('</div>',unsafe_allow_html=True)
    with c2:
        st.markdown('<div class="card"><div class="mini-title">Average Health Index Trend</div>',unsafe_allow_html=True)
        if df.empty or df["Time"].isna().all():
            st.info("The trend will appear after analysis data is available.")
        else:
            trend=df.dropna(subset=["Time","HI (%)"]).copy()
            trend["Month"]=trend["Time"].dt.to_period("M").dt.to_timestamp()
            trend=trend.groupby("Month",as_index=False)["HI (%)"].mean().tail(6)
            fig=px.line(trend,x="Month",y="HI (%)",markers=True)
            fig.update_layout(height=310,margin=dict(l=10,r=10,t=10,b=10),yaxis_title="Health Index (%)",xaxis_title="")
            fig.update_traces(line_width=3)
            st.plotly_chart(fig,use_container_width=True,config={"displayModeBar":False}, theme=None)
        st.markdown('</div>',unsafe_allow_html=True)
    c3,c4=st.columns([1.15,1])
    with c3:
        st.markdown('<div class="card"><div class="mini-title">Latest Data</div>',unsafe_allow_html=True)
        if df.empty:
            st.info("No latest data available.")
        else:
            latest=make_latest_assessment_df(df.copy())
            show_cols=[c for c in ["Transformer No","Time","HI (%)","Overall Condition"] if c in latest.columns]
            if show_cols:
                view=latest[show_cols].sort_values("Time",ascending=False).head(5).copy()
                if "Time" in view: view["Time"]=view["Time"].dt.strftime("%d/%m/%Y")
                st.dataframe(view,use_container_width=True,hide_index=True)
        st.markdown('</div>',unsafe_allow_html=True)
    with c4:
        st.markdown('<div class="card"><div class="mini-title">Quick Access</div>',unsafe_allow_html=True)
        if st.button("Start New Assessment",use_container_width=True,key="quick_start_assessment"):
            st.session_state.page="Input/Upload Data"
            st.session_state.input_method = "Input Manual"
            st.rerun()
        st.markdown('</div>',unsafe_allow_html=True)
    if not df.empty:
        latest_rows = df.sort_values("Time", ascending=False) if "Time" in df.columns else df
        if not latest_rows.empty:
            latest_record = latest_rows.iloc[0].to_dict()
            st.markdown("### Interactive Transformer View")
            st.caption("Putar model 3D, pilih komponen untuk inspeksi, atau aktifkan Interior / Cutaway View.")
            st.caption("Status komponen tersedia sebagai teks; model 3D bersifat tambahan dan memerlukan WebGL.")
            if st.checkbox("Tampilkan model 3D interaktif", value=False, key="dashboard_enable_3d"):
                render_interactive_transformer_3d_plotly(latest_record)
            else:
                status_rows = _component_status_data(latest_record)
                st.dataframe(pd.DataFrame([
                    {"Komponen": entry["label"], "Status": entry["status"],
                     "Indikasi": entry.get("evidence", "")}
                    for entry in status_rows.values()
                ]), use_container_width=True, hide_index=True)
    st.markdown('<div class="notice">ⓘ Make sure test data (BDV, WC, DGA, etc.) is complete for accurate analysis results.</div>',unsafe_allow_html=True)

def render_transformer_data():
    st.markdown('<div class="page-kicker">Data Management</div>',unsafe_allow_html=True)
    st.markdown('<div class="page-title">Transformer Data</div>',unsafe_allow_html=True)
    st.markdown('<div class="page-subtitle">List of transformer assessment results stored in your account.</div>',unsafe_allow_html=True)
    df=dashboard_dataframe()
    if df.empty:
        st.info("No transformer data available. Use Input / Upload Data to add an assessment.")
        return
    latest=make_latest_assessment_df(df.copy())
    cols=[c for c in ["Transformer No","Capacity","Voltage Class","Time","BDV","Water Content","HI (%)","Overall Condition","DGA Indication"] if c in latest.columns]
    st.dataframe(latest[cols].sort_values("Time",ascending=False),use_container_width=True,hide_index=True)

def render_duval_page(kind):
    title="Duval Triangle" if kind=="triangle" else "Duval Pentagon"
    st.markdown(f'<div class="page-kicker">DGA Diagnostics</div><div class="page-title">{title}</div>',unsafe_allow_html=True)
    st.markdown('<div class="page-subtitle">Diagnostic visualizations based on stored assessment results.</div>',unsafe_allow_html=True)
    df=dashboard_dataframe()
    if df.empty:
        st.info("No analysis results yet. Run an assessment first.")
        return
    latest=make_latest_assessment_df(df.copy())
    if latest.empty:
        st.info("No valid transformer data is available.")
        return
    render_duval_batch_visualization(latest)

def render_recommendation_page():
    st.markdown('<div class="page-kicker">Decision Support</div><div class="page-title">Recommendations</div>',unsafe_allow_html=True)
    st.markdown('<div class="page-subtitle">Maintenance action summary based on assessment results.</div>',unsafe_allow_html=True)
    df=dashboard_dataframe()
    if df.empty:
        st.info("No recommendations yet. Run an assessment first.")
        return
    latest=make_latest_assessment_df(df.copy()).sort_values("Time",ascending=False)
    cols=[c for c in ["Transformer No","Time","HI (%)","Overall Condition","Overall Follow-up","DGA Status 2019","Duval Method","Duval Diagnosis Zone","Severity","Action Required","Recommendation"] if c in latest.columns]
    st.dataframe(latest[cols].head(20),use_container_width=True,hide_index=True)
    if "Recommendation" in latest.columns:
        st.markdown("### Latest Recommendations")
        for _,row in latest.head(5).iterrows():
            st.markdown(f'<div class="card"><div class="mini-title">{escape(str(row.get("Transformer No","-")))}</div><div style="font-size:14px;color:var(--muted)">{escape(str(row.get("Recommendation","Not available")))}</div></div>',unsafe_allow_html=True)

